const PAGES={"/index.html":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"description\" content=\"MEFRIONのサポート、プライバシーポリシー、利用規約\"><title>MEFRION｜サポート</title><link rel=\"stylesheet\" href=\"/style.css\"></head><body><header><div class=\"shell top\"><a class=\"brand\" href=\"/\"><span>🐾</span>MEFRION</a><nav class=\"nav\" aria-label=\"メニュー\"><a href=\"/\" aria-current=\"page\">サポート</a><a href=\"/privacy.html\">プライバシー</a><a href=\"/terms.html\">利用規約</a></nav></div></header><main class=\"shell\"><section class=\"hero\"><div class=\"eyebrow\">HELP &amp; INFO</div><h1>困ったときは、ここから。</h1><p>MEFRIONの使い方やデータの扱いについてご案内します。</p></section><div class=\"notice\">MEFRIONは公開準備中です。このページは現在の開発・検証状況を説明するもので、App Storeでの一般提供開始をお知らせするものではありません。</div><div class=\"cards\"><a class=\"card\" href=\"/privacy.html\"><div class=\"icon\">🔒</div><h2>プライバシー</h2><p>写真やアカウント情報の扱いを確認できます。</p></a><a class=\"card\" href=\"/terms.html\"><div class=\"icon\">📝</div><h2>利用規約</h2><p>投稿や家族アルバムのルールを確認できます。</p></a><a class=\"card\" href=\"mailto:nextedovation@gmail.com?subject=MEFRION%E3%81%AE%E3%81%8A%E5%95%8F%E3%81%84%E5%90%88%E3%82%8F%E3%81%9B\"><div class=\"icon\">💌</div><h2>お問い合わせ</h2><p>不具合・通報・データに関する相談をメールで受け付けます。</p></a></div><section class=\"paper\"><h2>よくある質問</h2><div class=\"faq\"><h3>アカウントを削除したい</h3><p>アプリの「マイページ」→「アカウントを削除する」から手続きできます。ログインできない場合は下記のメールへご連絡ください。</p></div><div class=\"faq\"><h3>投稿やアカウントを通報したい</h3><p>アプリ内の通報メニューをご利用ください。利用できない場合は、対象の画面と状況をメールでお知らせください。</p></div><div class=\"faq\"><h3>家族アルバムの写真は公開されますか？</h3><p>アルバムの写真は初期状態で非公開です。公開投稿などの操作は、別途ご自身で選ぶ必要があります。</p></div><a class=\"button\" href=\"mailto:nextedovation@gmail.com?subject=MEFRION%E3%81%AE%E3%81%8A%E5%95%8F%E3%81%84%E5%90%88%E3%82%8F%E3%81%9B\">メールで問い合わせる</a><p class=\"mini\" style=\"margin-top:12px\">宛先：nextedovation@gmail.com。パスワードや確認コードは送らないでください。</p></section></main><footer><div class=\"shell\"><span>© 2026 MEFRION</span><span><a href=\"/privacy.html\">プライバシー</a> · <a href=\"/terms.html\">利用規約</a></span></div></footer></body></html>\n"},"/terms.html":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"description\" content=\"MEFRIONの利用規約\"><title>利用規約｜MEFRION</title><link rel=\"stylesheet\" href=\"/style.css\"></head><body><header><div class=\"shell top\"><a class=\"brand\" href=\"/\"><span>🐾</span>MEFRION</a><nav class=\"nav\" aria-label=\"メニュー\"><a href=\"/\">サポート</a><a href=\"/privacy.html\">プライバシー</a><a href=\"/terms.html\" aria-current=\"page\">利用規約</a></nav></div></header><main class=\"shell\"><section class=\"hero\"><div class=\"eyebrow\">TERMS</div><h1>利用規約</h1><p>ペットとの毎日を、安心して楽しむための約束です。</p></section><div class=\"notice\">2026年10月25日更新。現在のサービスの利用条件です。App Storeでの一般公開は準備中です。</div><section class=\"paper\"><h2>1. サービスと利用資格</h2><p>MEFRIONはペットの写真・動画を記録し、家族と共有し、公開投稿で交流できるサービスです。現行の提供方針は18歳以上、無料です。犬や猫を飼っていなくても登録できます。未成年者向け提供や有料機能を始める場合は、条件を別途案内します。</p></section><section class=\"paper\"><h2>2. アカウントと安全</h2><p>正しい情報で登録し、ログイン情報を安全に管理してください。他人へのなりすましや他人のアカウントの利用は禁止します。不正な利用が疑われる場合は、保護のために機能を制限することがあります。</p></section><section class=\"paper\"><h2>3. 写真・動画と公開範囲</h2><p>投稿する内容の権利は元の権利者に残ります。投稿者は、MEFRIONで保存、縮小、表示、選んだ公開範囲への配信を行うために必要な権限を持つことを確認してください。ほかの人や作品が写る場合は必要な許可を得てください。家族アルバムは初期非公開で、公開投稿や外部共有は別の操作で選びます。</p></section><section class=\"paper\"><h2>4. 禁止事項と対応</h2><p>権利侵害、他人の個人情報の無断公開、嫌がらせ、虐待の助長、差別、脅迫、性的な不適切内容、スパム、不正アクセスを禁止します。問題のある投稿やアカウントはアプリから通報できます。運営は内容を確認し、非表示や利用制限など必要な対応を行います。異議がある場合はお問い合わせください。</p></section><section class=\"paper\"><h2>5. そっくり機能</h2><p>写真の見た目から候補を探す機能です。血縁、同じ個体、健康状態を判定するものではありません。検索結果の近さは目安であり、正しさを保証するものではありません。</p></section><section class=\"paper\"><h2>6. 削除・変更・連絡</h2><p>アカウント削除はアプリのマイページから申請できます。削除が及ぶ範囲や情報の扱いは<a href=\"/privacy.html\">プライバシーポリシー</a>をご覧ください。サービスの重要な変更は事前に案内します。お問い合わせは <a href=\"mailto:nextedovation@gmail.com\">nextedovation@gmail.com</a> で受け付けます。</p></section></main><footer><div class=\"shell\"><span>© 2026 MEFRION</span><span><a href=\"/\">サポート</a> · <a href=\"/privacy.html\">プライバシー</a></span></div></footer></body></html>\n"},"/style.css":{"type":"text/css; charset=utf-8","body":":root{color-scheme:light;--ink:#352d34;--muted:#736a70;--pink:#d44e68;--soft:#fff2f3;--line:#eee5e5;--paper:#fffdfb}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#faf7f4;color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,\"Hiragino Kaku Gothic ProN\",\"Noto Sans JP\",sans-serif;line-height:1.8}a{color:#a92c49;text-underline-offset:3px}button{font:inherit}.shell{max-width:920px;margin:auto;padding:0 22px}header{background:rgba(255,253,251,.96);border-bottom:1px solid var(--line)}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:74px}.brand{font-size:20px;font-weight:800;letter-spacing:.04em;text-decoration:none;color:var(--pink)}.brand span{font-size:20px;margin-right:7px}.nav{display:flex;gap:16px;flex-wrap:wrap}.nav a{text-decoration:none;color:var(--ink);font-size:13px;font-weight:700}.nav a[aria-current=page]{color:var(--pink)}main{padding-top:42px;padding-bottom:72px}.hero{background:linear-gradient(135deg,#fff,#fff0f1);border:1px solid #f6dce1;border-radius:28px;padding:32px 34px;margin-bottom:22px}.eyebrow{font-size:12px;color:var(--pink);font-weight:800;letter-spacing:.14em}.hero h1{font-size:clamp(27px,5vw,42px);line-height:1.35;margin:9px 0}.hero p{margin:0;color:var(--muted)}.notice{padding:15px 18px;border-radius:18px;background:#fff9e8;color:#5b4a2e;border:1px solid #f1dfab;font-size:14px;margin:18px 0 24px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.card,.paper{background:var(--paper);border:1px solid var(--line);border-radius:22px;padding:22px}.card{text-decoration:none;color:var(--ink);transition:transform .15s,box-shadow .15s}.card:hover{transform:translateY(-3px);box-shadow:0 12px 28px #be899322}.icon{font-size:27px}.card h2{font-size:18px;margin:8px 0 4px}.card p{font-size:13px;color:var(--muted);margin:0}.paper{margin:14px 0}.paper h2{font-size:19px;line-height:1.45;margin:0 0 10px}.paper h3{font-size:15px;margin:20px 0 7px}.paper p,.paper li{font-size:14px;margin:0 0 9px}.paper ul{padding-left:1.2em;margin:0}.mini{font-size:12px;color:var(--muted)}.button{display:inline-block;padding:11px 22px;border-radius:999px;background:var(--pink);color:white;text-decoration:none;font-weight:800;margin-top:12px}.faq{border-top:1px solid var(--line);padding-top:14px;margin-top:14px}footer{border-top:1px solid var(--line);padding:24px 0 32px;color:var(--muted);font-size:12px}footer .shell{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}footer a{color:var(--muted)}@media(max-width:620px){.top{align-items:flex-start;flex-direction:column;gap:0;padding:15px 0}.nav{gap:13px}.hero{padding:26px 22px}.cards{grid-template-columns:1fr}main{padding-top:22px}.paper{padding:20px}}\n"},"/privacy.html":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"description\" content=\"MEFRIONのプライバシーポリシー\"><title>プライバシー｜MEFRION</title><link rel=\"stylesheet\" href=\"/style.css\"></head><body><header><div class=\"shell top\"><a class=\"brand\" href=\"/\"><span>🐾</span>MEFRION</a><nav class=\"nav\" aria-label=\"メニュー\"><a href=\"/\">サポート</a><a href=\"/privacy.html\" aria-current=\"page\">プライバシー</a><a href=\"/terms.html\">利用規約</a></nav></div></header><main class=\"shell\"><section class=\"hero\"><div class=\"eyebrow\">PRIVACY</div><h1>プライバシーポリシー</h1><p>あなたとペットの記録を、何に使い、どこで共有するかを説明します。</p></section><div class=\"notice\">2026年10月26日更新。現在提供している機能とデータの取り扱いを説明しています。App Storeでの一般公開は準備中です。</div><section class=\"paper\"><h2>1. 運営と連絡先</h2><p>運営表示名はMEFRIONです。プライバシーに関するご質問、開示・訂正・削除のご相談は <a href=\"mailto:nextedovation@gmail.com\">nextedovation@gmail.com</a> へお願いします。本人確認のため、必要な範囲で確認を行うことがあります。パスワードや確認コードの送付は求めません。</p></section><section class=\"paper\"><h2>2. 取り扱う情報と使い道</h2><ul><li>メールアドレス、ユーザーID、認証情報：登録、ログイン、確認メール、復旧、不正利用防止に使用します。パスワードそのものはアプリ運営者が閲覧できません。</li><li>プロフィール、ペットの名前・種類・犬種／猫種、写真・動画、撮影日、投稿文、コメント：アルバム、公開投稿、検索、表示に使用します。</li><li>フォロー、いいね、保存、通報、ブロック、通知設定：交流機能と安全管理に使用します。</li><li>アプリ・通信の技術情報：障害調査、不正利用対策、サービス改善に必要な範囲で扱います。</li></ul></section><section class=\"paper\"><h2>3. 写真の公開と家族共有</h2><p>家族アルバムは初期状態で非公開です。招待された家族のみが閲覧でき、公開投稿、そっくり候補への参加、外部共有にはそれぞれ別の操作が必要です。公開投稿はほかの利用者から閲覧されます。外部に保存・再共有されたコピーはMEFRIONから回収できません。</p><p>そっくり検索では、選んだ写真から端末内で作った特徴データと種類を検索サーバーへ送り、候補を比較します。検索の入力写真そのものは、その操作によってサーバーへアップロードしません。写真をアルバムや投稿へ保存する操作は別です。検索履歴には、どの写真から探したか分かる小さな入力画像と検索結果を、この端末内に24時間保存します。履歴はアプリから削除でき、入力画像を検索サーバーの履歴へ保存しません。</p></section><section class=\"paper\"><h2>4. 外部サービスと国外での取扱い</h2><p>認証、データベース、写真保存にはSupabaseを利用し、確認メールの配信にはBrevoを利用しています。サポート・規約・共有ページと運営画面の配信にはVercelを利用し、これらのWebページへの接続に伴うIPアドレスなどの技術情報が処理されます。これらの事業者がサービス提供のために必要な情報を処理します。本番のデータベースと写真・動画の保存先はSupabaseの東京リージョンです。メール配信などに伴い、委託先のサービス基盤で国外の処理が行われる場合があります。広告目的の追跡や、ユーザーの写真を汎用AIの学習へ自動転用することは予定していません。</p></section><section class=\"paper\"><h2>5. 保存・削除・安全管理</h2><p>情報は利用目的に必要な期間保管します。アプリ内で写真・投稿を削除したり、用途の同意を撤回したりできます。アカウント削除は「マイページ」から申請できます。受付時に公開表示とアクセスを停止し、残るファイルと認証情報は削除処理で順次消去します。法令上必要な情報や削除・復元の安全確認に必要な最小限の記録は、必要な期間だけ保持する場合があります。</p><p>通信の保護、アクセス権限の分離、アプリのKeychain利用などにより情報を守ります。ファイル・認証情報の削除処理と期限切れデータの整理はサーバーで定期実行します。暗号化したバックアップを別の保存先に保管し、復元時にも削除済みデータを再公開しないための記録を使います。外部サービス側で必要な技術記録やバックアップの保持については、各サービスの運用に従います。</p><p>不正利用の調査と障害対応のため、アクセスの日時、応答結果、対象機能、参考となる国情報、週ごとに変わる接続元の匿名化識別子などを記録します。この監視記録に元のIPアドレス、メールアドレス、パスワード、認証コード、リクエスト本文は保存しません。詳細は最大30日、時間別の集計と対応記録は最大90日を目安に保持し、運営権限と二段階認証で閲覧を制限します。外部サービス自体の技術ログは各サービスの運用に従います。</p></section><section class=\"paper\"><h2>6. 変更と問い合わせ</h2><p>サービスや情報の扱いを変更する際は、このページを更新します。重要な変更はアプリ内などで案内し、必要な場合は同意を取り直します。ご不明点は <a href=\"mailto:nextedovation@gmail.com\">nextedovation@gmail.com</a> へご連絡ください。</p></section></main><footer><div class=\"shell\"><span>© 2026 MEFRION</span><span><a href=\"/\">サポート</a> · <a href=\"/terms.html\">利用規約</a></span></div></footer></body></html>\n"},"/console/":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"ja\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"mefrion-config\" content=\"/console/config.json\"><title>MEFRION クラウド運営管理</title><link rel=\"stylesheet\" href=\"/console/base.css\"><link rel=\"stylesheet\" href=\"/console/admin.css\"><script src=\"/console/cloud.js\" defer></script><script src=\"/console/seed.js\" defer></script><link rel=\"stylesheet\" href=\"/console/security.css\"><script src=\"/console/security.js\" defer></script><body><header><span>MEFRION / クラウド運営管理</span><a href=\"/console/\">一括管理へ</a></header><main><h1 id=\"main-heading\">運営管理</h1><p class=\"notice\">MEFRIONの運営管理。運営権限と認証アプリのMFAが必要です。利用者の家族アルバム原本と通報者の情報は取得しません。運営素材は担当権限で管理します。権限を付与された担当者だけが利用できます。</p><form id=\"login\"><label>運営アカウントのメール<input id=\"email\" type=\"email\" autocomplete=\"username\" required></label><label>パスワード<input id=\"password\" type=\"password\" autocomplete=\"current-password\" required></label><button>ログイン</button></form><button id=\"email-login-toggle\" type=\"button\">メールのコードでログイン・登録</button><form id=\"email-login\" hidden><label>運営アカウントのメール<input id=\"otp-email\" type=\"email\" autocomplete=\"email\" required></label><p>初めての方はMEFRIONアカウントが作成されます。登録だけでは運営権限は付与されません。</p><label><input id=\"otp-consent\" type=\"checkbox\" required>18歳以上で、<a href=\"/terms\" target=\"_blank\" rel=\"noopener\">利用条件</a>と<a href=\"/privacy\" target=\"_blank\" rel=\"noopener\">プライバシーポリシー</a>を確認しました</label><button>確認コードを送る</button></form><form id=\"email-verify\" hidden><label>メールの確認コード<input id=\"email-code\" type=\"text\" inputmode=\"numeric\" pattern=\"[0-9]{6,8}\" maxlength=\"8\" autocomplete=\"one-time-code\" required></label><button>コードで続ける</button></form><section id=\"enroll\" hidden><h2>認証アプリの登録</h2><p>MEFRION運営アカウントに認証アプリを登録します。登録だけで運営権限は付与されません。コード・秘密は他の人へ送らないでください。</p><button id=\"start-enroll\">本人が認証アプリ登録を開始する</button><div id=\"enroll-instructions\" hidden><p>認証アプリで新しい項目を追加し、名前を「MEFRION operator」にして、次の設定キーを登録してください。以前のSupabase用とは別の6桁が表示されます。</p><code id=\"enroll-secret\"></code><button id=\"copy-enroll-key\" type=\"button\">設定キーをコピー</button></div></section><form id=\"mfa\" hidden novalidate><label>認証アプリの6桁コード<input id=\"code\" type=\"password\" inputmode=\"numeric\" pattern=\"[0-9]{6}\" maxlength=\"12\" aria-describedby=\"mfa-help status\" autocomplete=\"one-time-code\" required></label><button type=\"submit\">この6桁で確認する</button><p id=\"mfa-feedback\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\"></p><p id=\"mfa-help\">入力したあと、このボタンを押してください。今回「MEFRION operator」として追加した認証アプリの6桁を使います。メールの確認コード・以前のSupabase用とは別です。</p></form><button id=\"restart-enroll\" type=\"button\" hidden>認証アプリを登録し直す</button><button id=\"cancel-login\">ログインを取り消す</button><details><summary>接続に困ったとき</summary><button id=\"check-connection\" type=\"button\">接続を確認</button><p>メールの送信やアカウントの作成は行いません。</p></details><p id=\"status\" role=\"status\" aria-live=\"polite\"></p><div id=\"session\" hidden><button id=\"security-nav\" type=\"button\">セキュリティ</button><button id=\"reports-nav\" type=\"button\">通報</button><details><summary>サーバー稼働状況</summary><button id=\"server-health-refresh\">現在の状態を見る</button><pre id=\"server-health-output\"></pre></details><button id=\"seed-refresh\">運営Pet・下書きを取得</button><button id=\"refresh\">最新の通報を取得</button><button id=\"logout\">ログアウト</button></div><section id=\"security-section\" hidden aria-label=\"セキュリティ監視\">\n <div class=\"sec-layout\"><aside class=\"sec-sidebar\"><a class=\"sec-wordmark\" href=\"/console/security\"><span class=\"sec-shield\">M</span> MEFRION<span class=\"sec-wordmark-small\">SECURITY</span></a><p class=\"sec-side-caption\">運営ワークスペース</p><nav aria-label=\"監視メニュー\"><button data-sec-view=\"overview\" class=\"active\">◈ 概要</button><button data-sec-view=\"events\">≋ 検知ログ</button><button data-sec-view=\"incidents\">⚑ インシデント <span id=\"sec-nav-incidents\">—</span></button><button data-sec-view=\"coverage\">◎ 監視範囲</button></nav><div class=\"sec-side-bottom\"><span class=\"sec-dot\"></span> 運営アカウント限定<p>二段階認証で保護されています</p></div></aside>\n <div class=\"sec-main\"><header class=\"sec-top\"><div><p class=\"sec-eyebrow\">SECURITY OPERATIONS</p><h1>セキュリティ</h1><p class=\"sec-sub\">起きていることを、記録から確かめる。</p></div><div class=\"sec-controls\"><label class=\"sec-sr\" for=\"sec-hours\">集計期間</label><select id=\"sec-hours\"><option value=\"24\">直近24時間</option><option value=\"168\">直近7日間</option><option value=\"720\">直近30日間</option></select><button id=\"sec-refresh\" type=\"button\">↻ 更新</button></div></header>\n <div class=\"sec-statusline\"><span id=\"sec-connection\" class=\"sec-status-pill\">接続を確認中</span><span id=\"sec-updated\">—</span><label><input id=\"sec-auto\" type=\"checkbox\" checked>概要を30秒ごとに更新</label></div>\n <div id=\"sec-message\" role=\"status\" aria-live=\"polite\"></div>\n <div class=\"sec-view\" data-sec-panel=\"overview\"><div class=\"sec-metrics\"><article><span>記録したシグナル</span><strong id=\"sec-signals\">—</strong><small>通常のエラー・監査記録も含む</small></article><article><span>攻撃の疑い</span><strong id=\"sec-suspected\">—</strong><small>探索・不正入力のパターン検知</small></article><article><span>拒否・制限の応答</span><strong id=\"sec-denied\">—</strong><small>401 / 403 / 404 / 405 / 429など</small></article><article><span>未対応のインシデント</span><strong id=\"sec-open\">—</strong><small>全期間・対応待ちの件数</small></article></div>\n <section class=\"sec-card\"><div class=\"sec-card-head\"><div><h2>シグナルの推移</h2><p>記録件数と、攻撃が疑われるパターン</p></div><div class=\"sec-legend\"><span>● 記録件数</span><span>● 攻撃の疑い</span></div></div><div id=\"sec-chart\" class=\"sec-chart\" role=\"img\" aria-label=\"集計結果の取得待ち\"></div><p class=\"sec-footnote\">時間単位の集計です。過去の未収集データは表示しません。</p></section>\n <div class=\"sec-grid-two\"><section class=\"sec-card\"><h2>検知の内訳</h2><div id=\"sec-types\" class=\"sec-breakdown\"></div></section><section class=\"sec-card\"><h2>対象になった場所</h2><div id=\"sec-targets\" class=\"sec-breakdown\"></div></section></div>\n <section class=\"sec-card\"><div class=\"sec-card-head\"><div><h2>繰り返し観測した接続元</h2><p>匿名化した識別子。個人や攻撃者の特定ではありません。</p></div></div><div id=\"sec-sources\"></div></section></div>\n <section class=\"sec-view sec-card\" data-sec-panel=\"events\" hidden><div class=\"sec-card-head\"><div><h2>検知ログ</h2><p>詳細を選んで、応答結果と記録IDを確認できます。</p></div><button id=\"sec-export\" type=\"button\">CSVを書き出す</button></div><div class=\"sec-filters\"><label>種類<select id=\"sec-kind\"><option value=\"\">すべての種類</option><option value=\"secret_probe\">秘密ファイル探索の疑い</option><option value=\"path_traversal\">パス探索の疑い</option><option value=\"injection_probe\">不正入力の疑い</option><option value=\"auth_denied\">認証拒否</option><option value=\"access_denied\">アクセス拒否</option><option value=\"rate_limited\">回数制限</option><option value=\"not_found\">404応答</option><option value=\"method_denied\">未対応のメソッド</option><option value=\"account_retirement\">退会の受付</option><option value=\"server_error\">サーバーエラー</option><option value=\"operator_changed\">運営権限の変更</option></select></label><label>重要度<select id=\"sec-severity\"><option value=\"\">すべて</option><option value=\"critical\">緊急</option><option value=\"high\">高</option><option value=\"medium\">中</option><option value=\"low\">低</option><option value=\"info\">情報</option></select></label><label>記録元<select id=\"sec-source\"><option value=\"\">すべて</option><option value=\"vercel\">Vercelサイト</option><option value=\"edge:private-image\">非公開画像API</option><option value=\"edge:public-image\">公開画像API</option><option value=\"edge:public-video\">公開動画API</option><option value=\"app_audit\">アプリの監査記録</option></select></label></div><div class=\"sec-table-wrap\"><table><thead><tr><th>記録時刻</th><th>種類</th><th>重要度</th><th>対象</th><th>結果</th><th>詳細</th></tr></thead><tbody id=\"sec-events\"></tbody></table></div><p id=\"sec-event-count\" class=\"sec-footnote\">—</p><button id=\"sec-more\" type=\"button\" hidden>さらに読み込む</button></section>\n <section class=\"sec-view sec-card\" data-sec-panel=\"incidents\" hidden><div class=\"sec-card-head\"><div><h2>インシデント</h2><p>同じ接続元で5分間に10件以上のシグナル、またはサーバーエラーをまとめます。</p></div></div><div id=\"sec-incidents\"></div></section>\n <section class=\"sec-view\" data-sec-panel=\"coverage\" hidden><div class=\"sec-card\"><h2>監視範囲と収集状態</h2><p>この画面に表示できる記録と、別途連携が必要な記録を区別しています。</p><div id=\"sec-coverage\"></div><div class=\"sec-coverage-static\"><article><h3>Vercel Firewall / DDoS対策</h3><span class=\"sec-badge neutral\">外部ログ未連携</span><p>Vercelがアプリ到達前に遮断した通信は、ここの件数に含まれません。</p><a href=\"https://vercel.com/toshiki-endos-projects/mefrion/firewall\" target=\"_blank\" rel=\"noopener noreferrer\">Vercelの公式画面で確認 ↗</a></article><article><h3>Supabase Auth / DB REST / Storageへの直接通信</h3><span class=\"sec-badge neutral\">拒否ログ未連携</span><p>Edge Functionを通らない直接アクセスの拒否は、この画面だけでは網羅できません。</p><a href=\"https://supabase.com/dashboard/project/pbnimpqrthvznbwewtcf/logs\" target=\"_blank\" rel=\"noopener noreferrer\">Supabaseの公式ログを開く ↗</a></article></div></div><div class=\"sec-card\"><h2>記録の取り扱い</h2><ul id=\"sec-limitations\"></ul><p>詳細ログは最大30日・10万件を目安に毎分整理し、時間別集計は最大90日、対応記録は最終更新から最大90日保存します。IPアドレス・メールアドレス・パスワード・認証コード・リクエスト本文は保存しません。ログの保存上限や送信エラーによる欠落がある場合は収集状態へ表示します。</p><p id=\"sec-retention\" class=\"sec-footnote\"></p></div></section>\n <footer class=\"sec-footer\">検知は調査の手がかりです。攻撃の確定や侵入成功を示すものではありません。<span id=\"sec-quality\"></span></footer>\n </div></div>\n <dialog id=\"sec-detail\" aria-labelledby=\"sec-detail-title\"><div class=\"sec-detail-head\"><h2 id=\"sec-detail-title\">記録の詳細</h2><button id=\"sec-detail-close\" type=\"button\" aria-label=\"詳細を閉じる\">×</button></div><dl id=\"sec-detail-body\"></dl><p>対象URLは個人情報を除去した形式です。元のIPアドレスや送信内容は記録していません。</p></dialog>\n</section>\n<!-- security-panel-end --><section id=\"confirmation\" hidden><h2>対応内容を確認</h2><p id=\"confirm-target\"></p><p id=\"confirm-reason\"></p><button id=\"confirm-review\">この対応を記録する</button><button id=\"cancel-review\">取り消す</button></section><section id=\"queue\"></section><section id=\"seed-section\" hidden><h1>運営Pet・承認・予約</h1><p>個別のPetログインは不要です。編集・承認・配信の権限をサーバーで確認します。運営が制作または管理する投稿が含まれる場合があることを、ヘルプと利用条件へ説明します。架空の反応・実体験は作成しません。</p><p id=\"seed-metrics\"></p><p id=\"seed-permissions\"></p><details id=\"seed-policy\"><summary>UGC優先比率・監査</summary><label>運営投稿の上限比率<input id=\"seed-ratio\" type=\"number\" min=\"0\" max=\"1\" step=\"0.05\" value=\"0.5\"></label><button id=\"seed-ratio-save\">上限比率を保存</button><button id=\"seed-audit-refresh\">操作監査を表示</button><div id=\"seed-audit\"></div></details><label>投稿主体<select id=\"seed-publisher\"></select></label><label>一括登録CSV<textarea id=\"seed-csv\" rows=\"6\" placeholder=\"key,name,species,breed,introduction,source\"></textarea></label><button id=\"seed-preview-button\">登録前プレビュー</button><div id=\"seed-preview\"></div><button id=\"seed-create\">プレビューしたPetを一括登録</button><label>運営Petを検索<input id=\"seed-search\" type=\"search\"></label><h2>投稿の一括下書き</h2><p>写真IDは素材の一覧で確認してください。複数枚は | で区切ります。入力予定日時は承認後に予約を確定します。</p><label>一括投稿CSV<textarea id=\"seed-post-csv\" rows=\"5\" placeholder=\"pet_id,photo_ids,body,planned_at\"></textarea></label><button id=\"seed-batch-preview\">一括投稿プレビュー</button><div id=\"seed-batch-list\"></div><button id=\"seed-batch-save\">確認した投稿を一括下書き保存</button><h2>投稿予定カレンダー</h2><div id=\"seed-calendar\"></div><div id=\"seed-list\"></div></section></main></body></html>\n"},"/console/cloud.js":{"type":"text/javascript; charset=utf-8","body":"'use strict';\nconst $=id=>document.getElementById(id);\nlet config,token,factor,expires=0,busy=false,generation=0,pendingReview=null,pendingEmail=null,mfaComplete=false;\nlet panel=document.body?.dataset?.consolePanel||'reports';\nconst status=message=>{$('status').textContent=message;const feedback=$('mfa-feedback');if(feedback)feedback.textContent=$('mfa').hidden?'':message;};\n// Map documented error codes; never display raw authentication responses.\nconst authErrors={\n mfa_verification_failed:'コードが一致しません。今回追加した「MEFRION operator」の新しい6桁を入力してください。',\n mfa_challenge_expired:'コードの確認期限が切れました。認証アプリの新しい6桁でもう一度お試しください。',\n mfa_ip_address_mismatch:'途中で通信経路が変わりました。同じWi-Fiかモバイル回線で、もう一度確認してください。',\n mfa_factor_not_found:'認証アプリの登録が見つかりません。メールでログインし直してください。',\n mfa_factor_name_conflict:'確認待ちの登録があります。メールでログインし直すと続きから確認できます。',\n mfa_verification_rejected:'確認が制限されています。少し時間をおいてお試しください。',\n otp_expired:'メールの確認コードが違うか期限切れです。新しいメールのコードでお試しください。'\n};\nasync function request(path,body,auth=token,clearOnForbidden=true,method=body===undefined?'GET':'POST'){\n const headers={apikey:config.anon_key,'Content-Type':'application/json'};if(auth)headers.Authorization='Bearer '+auth;\n const response=await fetch(config.url+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body),cache:'no-store',credentials:'omit',signal:typeof AbortSignal==='undefined'?undefined:AbortSignal.timeout(20000)});\n if(!response.ok){\n  let errorCode='';try{const result=await response.json();const value=result.error_code||result.code;if(typeof value==='string'&&/^[a-z_]{1,80}$/.test(value))errorCode=value;}catch{}\n  const mfaError=errorCode.startsWith('mfa_');\n  if(((response.status===401&&!mfaError)||(response.status===403&&clearOnForbidden&&!mfaError))&&auth&&auth===token)clear();\n  const error=Error(authErrors[errorCode]||(response.status===429?'確認が混み合っています。少し時間をおいてお試しください。':response.status===401?'ログインが切れました。メールでログインし直してください。':response.status===403?'運営権限と認証を確認してください。':'操作できません。入力内容と接続を確認してください。'));\n  error.status=response.status;error.code=errorCode;throw error;\n }\n return response.status===204?null:response.json();\n}\nconst rpc=(name,body={})=>request('/rest/v1/rpc/mefrion_'+name,body);\ndocument.getElementById('server-health-refresh')?.addEventListener('click',()=>perform(async()=>{\n const result=await rpc('operator_cloud_health');\n const output=document.getElementById('server-health-output');\n if(output)output.textContent=JSON.stringify(result,null,2);\n status('サーバーの稼働状況を取得しました。');\n}));\nfunction clear(){if(typeof clearSecurity==='function')clearSecurity();$('restart-enroll').hidden=true;mfaComplete=false;pendingEmail=null;$('email-code').value='';$('email-login').hidden=true;$('email-verify').hidden=true;$('email-login-toggle').hidden=false;$('main-heading').textContent='運営管理';if(typeof clearSeed===\"function\")clearSeed();generation++;token=null;factor=null;expires=0;$('queue').replaceChildren();$('queue').hidden=false;$('confirmation').hidden=true;pendingReview=null;$('password').value='';$('code').value='';$('session').hidden=true;$('refresh').hidden=false;$('mfa').hidden=true;$('enroll').hidden=true;$('enroll-instructions').hidden=true;$('enroll-secret').textContent='';$('start-enroll').hidden=false;$('login').hidden=false;}\nasync function perform(operation){if(busy)return;busy=true;for(const button of document.querySelectorAll('button'))button.disabled=true;try{await operation();}catch(error){status(error.name==='TimeoutError'||error.name==='AbortError'?'通信に時間がかかっています。もう一度お試しください。':error instanceof TypeError?'通信できませんでした。接続を確認して、もう一度お試しください。':error.message);}finally{busy=false;for(const button of document.querySelectorAll('button'))button.disabled=false;}}\nfunction node(tag,text){const result=document.createElement(tag);if(text!==undefined)result.textContent=text;return result;}\nasync function refresh(){\n if(panel==='security'&&typeof refreshSecurity==='function')return refreshSecurity();\n $('main-heading').textContent='通報を確認する';\n $('seed-section').hidden=true;$('queue').hidden=false;$('queue').replaceChildren();if(!token || Date.now()/1000>=expires){clear();throw Error('ログインが切れました。再度ログインしてください。');}\n const stamp=generation;let rows;try{rows=await request('/rest/v1/rpc/mefrion_operator_queue',{},token,false);}catch(error){if(error.status===403){status('二段階認証が完了しました。運営権限の有効化をお待ちください。');return;}throw error;}if(stamp!==generation)return;\n for(const report of rows){\n  const card=node('article');card.className='card';card.append(node('h2',report.comment_id?'コメントの通報':'Pet・投稿の通報'),node('p',report.reason),node('p',report.note),node('p',report.snapshot.body||report.snapshot.name||''));\n  const history=node('p',`対応履歴 ${report.reviews.length}件・異議 ${report.appeals.length}件`);card.append(history);\n  const assigned=report.assignment||{version:0,mine:false,assigned:false};card.append(node('p',assigned.assigned?(assigned.mine?'担当：あなた':'担当：別の担当者'):'担当：未割当'));const claim=node('button',assigned.mine?'担当を解除する':'この通報を担当する');claim.hidden=assigned.assigned&&!assigned.mine;claim.addEventListener('click',()=>perform(async()=>{await rpc('operator_claim',{p_report:report.id,p_version:assigned.version,p_claim:!assigned.mine});await refresh();}));card.append(claim);\n  for(const appeal of report.appeals)card.append(node('p','異議内容：'+appeal.note));\n  const select=node('select');select.setAttribute('aria-label','対応内容');\n  for(const [value,label] of [['dismiss','確認終了'],[report.comment_id?'hide_comment':'hide_post',report.comment_id?'コメントを非表示':'投稿を非表示'],['suspend_account','相手の全Pet・公開活動を停止'],['restore_account','公開活動の停止を解除']]){const option=node('option',label);option.value=value;select.append(option);}\n  const note=node('textarea');note.maxLength=1000;note.placeholder='内部の判断理由（必須）';note.setAttribute('aria-label','判断理由');\n  const button=node('button','対応を記録');let requestKey=crypto.randomUUID();const changed=()=>{requestKey=crypto.randomUUID();};note.addEventListener('input',changed);select.addEventListener('change',changed);\n  button.addEventListener('click',()=>perform(async()=>{\n   if(!note.value.trim())throw Error('判断理由を入力してください。');\n   pendingReview={p_report:report.id,p_decision:select.value,p_note:note.value,p_request_key:requestKey};\n   $('confirm-target').textContent=(report.comment_id?'コメントの通報':'Pet・投稿の通報')+'：'+select.selectedOptions[0].textContent;\n   $('confirm-reason').textContent='内部の判断理由：'+note.value;$('confirmation').hidden=false;$('queue').hidden=true;\n  }));select.hidden=note.hidden=button.hidden=assigned.assigned&&!assigned.mine;card.append(select,note,button);$('queue').append(card);\n }\n status(`運営権限とMFAを確認しました。通報 ${rows.length}件。`);\n}\n$('login').addEventListener('submit',event=>{event.preventDefault();perform(async()=>{\n const credentials={email:$('email').value,password:$('password').value};clear();const stamp=generation;const configPath=document.querySelector('meta[name=\"mefrion-config\"]')?.content||'/v1/development/cloud-public-config';config=await (await fetch(configPath,{cache:'no-store'})).json();\n const result=await request('/auth/v1/token?grant_type=password',credentials,null);$('password').value='';\n await acceptSession(result,stamp);\n});});\n$('start-enroll').addEventListener('click',()=>perform(async()=>{\n const stamp=generation;const result=await request('/auth/v1/factors',{factor_type:'totp',friendly_name:'MEFRION operator'});if(stamp!==generation)return;\n factor=result.id;$('restart-enroll').hidden=false;$('enroll-secret').textContent=result.totp.secret;$('enroll-instructions').hidden=false;$('start-enroll').hidden=true;$('mfa').hidden=false;status('設定キーを認証アプリへ登録し、コードを入力してください。');\n}));\n$('mfa').addEventListener('submit',event=>{event.preventDefault();perform(async()=>{\n const code=$('code').value.normalize('NFKC').replace(/[\\s-]/g,'');\n if(!/^[0-9]{6}$/.test(code))throw Error('認証アプリの6桁を入力してください。メールの確認コードとは別です。');\n if(!token||!factor)throw Error('メールでログインし直してください。');\n status('コードを確認しています…');\n const stamp=generation;const challenge=await request('/auth/v1/factors/'+factor+'/challenge',{});\n const result=await request('/auth/v1/factors/'+factor+'/verify',{challenge_id:challenge.id,code});$('code').value='';if(stamp!==generation)return;\n mfaComplete=true;token=result.access_token;expires=Date.now()/1000+result.expires_in;$('enroll').hidden=true;$('enroll-secret').textContent='';$('mfa').hidden=true;$('restart-enroll').hidden=true;$('session').hidden=false;\n let seedOnly=false;try{const permissions=await request('/rest/v1/rpc/mefrion_seed_permissions',{},token,false);seedOnly=(permissions.edit||permissions.approve)&&!permissions.publish;}catch(error){}\n $('refresh').hidden=seedOnly;\n if(seedOnly){await refreshSeed();status('運営権限とMFAを確認しました。担当範囲の素材・下書きを管理できます。');}else await refresh();\n});});\n$('confirm-review').addEventListener('click',()=>perform(async()=>{\n if(!pendingReview)return;const payload=pendingReview;const stamp=generation;await rpc('operator_review',payload);if(stamp!==generation)return;\n pendingReview=null;$('confirmation').hidden=true;$('queue').hidden=false;await refresh();status('対応を記録しました。');\n}));\n$('cancel-review').addEventListener('click',()=>{pendingReview=null;$('confirmation').hidden=true;$('queue').hidden=false;status('対応を取り消しました。');});\n$('cancel-login').addEventListener('click',()=>{clear();status('ログインを取り消しました。');});\n$('refresh').addEventListener('click',()=>perform(refresh));$('logout').addEventListener('click',()=>perform(async()=>{const previous=token;clear();if(previous)await request('/auth/v1/logout',{},previous);status('ログアウトしました。');}));\nwindow.addEventListener('pagehide',clear);document.addEventListener('visibilitychange',()=>{if(document.hidden){$('enroll-secret').textContent='';$('queue').replaceChildren();if(typeof clearSeed==='function')clearSeed();pendingReview=null;$('confirmation').hidden=true;$('confirm-target').textContent='';$('confirm-reason').textContent='';}else if(mfaComplete && token && !busy)perform(async()=>{const permissions=await request('/rest/v1/rpc/mefrion_seed_permissions',{},token,false);if((permissions.edit||permissions.approve)&&!permissions.publish){$('refresh').hidden=true;await refreshSeed();}else await refresh();});});\n\nasync function acceptSession(result,stamp){\n if(stamp!==generation)return;mfaComplete=false;token=result.access_token;expires=Date.now()/1000+result.expires_in;\n const user=await request('/auth/v1/user');const verified=(user.factors||[]).filter(item=>item.factor_type==='totp' && item.status==='verified');\n if(!verified.length){\n  $('login').hidden=true;$('email-login').hidden=true;$('email-verify').hidden=true;$('email-login-toggle').hidden=true;\n  const pending=(user.factors||[]).find(item=>item.factor_type==='totp'&&item.status==='unverified');\n  if(pending){factor=pending.id;$('mfa').hidden=false;$('restart-enroll').hidden=false;status('確認待ちの登録があります。今回追加した運営画面用の6桁を入力してください。未追加なら「認証アプリを登録し直す」へ。');}\n  else{$('enroll').hidden=false;status('この運営画面用の認証アプリ登録が必要です。以前のSupabase用とは別です。');}\n  return;\n }\n factor=verified[0].id;$('login').hidden=true;$('email-login').hidden=true;$('email-verify').hidden=true;$('email-login-toggle').hidden=true;$('mfa').hidden=false;status('認証アプリのコードを入力してください。');\n}\n\nasync function loadConfig(){const path=document.querySelector('meta[name=\"mefrion-config\"]')?.content||'/console/config.json';const response=await fetch(path,{cache:'no-store',credentials:'omit'});if(!response.ok)throw Error('接続を確認してください。');config=await response.json();}\n$('email-login-toggle').addEventListener('click',()=>{clear();$('login').hidden=true;$('email-login-toggle').hidden=true;$('email-login').hidden=false;status('メールに届くコードで続けます。');});\n$('email-login').addEventListener('submit',event=>{event.preventDefault();perform(async()=>{\n if(!$('otp-consent').checked)throw Error('利用条件を確認してください。');\n const email=$('otp-email').value.trim();const stamp=generation;await loadConfig();\n await request('/auth/v1/otp',{email,create_user:true},null);if(stamp!==generation)return;\n pendingEmail=email;$('email-login').hidden=true;$('email-verify').hidden=false;status('メールに届いた確認コードを入力してください。');\n});});\n$('email-verify').addEventListener('submit',event=>{event.preventDefault();perform(async()=>{\n if(!pendingEmail)throw Error('確認コードの送信からやり直してください。');const stamp=generation;\n const result=await request('/auth/v1/verify',{email:pendingEmail,token:$('email-code').value.trim(),type:'email'},null);\n $('email-code').value='';pendingEmail=null;await acceptSession(result,stamp);\n});});\n\n$('check-connection').addEventListener('click',()=>perform(async()=>{\n await loadConfig();\n const result=await fetch(config.url+'/auth/v1/settings',{headers:{apikey:config.anon_key},cache:'no-store',credentials:'omit'});\n if(!result.ok)throw Error('認証サーバーに接続できませんでした。時間をおいてお試しください。');\n // Nonexistent reserved address, create_user false: exercises POST/CORS without\n // sending mail or creating an account. Do not display response bodies.\n const probe=await fetch(config.url+'/auth/v1/otp',{method:'POST',headers:{apikey:config.anon_key,'Content-Type':'application/json'},body:JSON.stringify({email:'mefrion-connectivity-check@example.invalid',create_user:false}),cache:'no-store',credentials:'omit'});\n if(![200,400,422,429].includes(probe.status))throw Error('認証サーバーに接続できませんでした。時間をおいてお試しください。');\n status('認証サーバーとの通信を確認できました。メールは送信していません。');\n}));\n\n$('restart-enroll').addEventListener('click',()=>perform(async()=>{\n const stamp=generation;const user=await request('/auth/v1/user');\n const pending=(user.factors||[]).find(item=>item.id===factor&&item.factor_type==='totp'&&item.status==='unverified');\n if(!pending)throw Error('登録状態が変わりました。メールでログインし直してください。');\n await request('/auth/v1/factors/'+pending.id,undefined,token,true,'DELETE');\n if(stamp!==generation)return;factor=null;$('code').value='';$('mfa').hidden=true;$('restart-enroll').hidden=true;\n $('enroll').hidden=false;$('enroll-instructions').hidden=true;$('enroll-secret').textContent='';$('start-enroll').hidden=false;\n status('確認前の登録を取り消しました。新しい設定キーで認証アプリへ追加してください。確認済みの登録は変更していません。');\n}));\n\n$('copy-enroll-key').addEventListener('click',()=>perform(async()=>{\n const key=$('enroll-secret').textContent;if(!key)throw Error('設定キーが消去されています。「認証アプリを登録し直す」から新しく追加してください。');\n await navigator.clipboard.writeText(key);status('設定キーをコピーしました。認証アプリで新しい項目に登録し、そこで表示される6桁を入力してください。');\n}));\n"},"/console/seed.js":{"type":"text/javascript; charset=utf-8","body":"'use strict';\nlet seedSnapshot=null,seedItems=[],seedKey=crypto.randomUUID(),seedPreviewURLs=[],seedGeneration=0,seedPermissions={},seedPreviewBytes=0;\nfunction releaseSeedPreviews(){for(const url of seedPreviewURLs)URL.revokeObjectURL(url);seedPreviewURLs=[];seedPreviewBytes=0;}\nfunction seedStamp(){return generation+\":\"+seedGeneration;}\nfunction clearSeed(){seedGeneration++;seedPermissions={};$('seed-audit').replaceChildren();$('seed-permissions').textContent='';releaseSeedPreviews();seedBatchItems=[];$('seed-post-csv').value='';$('seed-batch-list').replaceChildren();$('seed-calendar').replaceChildren();$('seed-search').value='';$('seed-metrics').textContent='';$('seed-publisher').replaceChildren();seedSnapshot=null;seedItems=[];seedKey=crypto.randomUUID();$('seed-list').replaceChildren();$('seed-preview').replaceChildren();$('seed-csv').value='';$('seed-section').hidden=true;}\nasync function refreshSeed(){\n $('main-heading').textContent='運営Petの一括管理';const stamp=seedStamp();const data=await rpc('seed_list');if((stamp!==seedStamp() || document.hidden))return;seedPermissions=await rpc('seed_permissions');if(stamp!==seedStamp() || document.hidden)return;seedSnapshot=data;$('queue').hidden=true;$('seed-permissions').textContent='担当権限：'+Object.keys(seedPermissions).filter(k=>seedPermissions[k]).join(' / ')+'（サーバーでも毎回確認）';for(const id of ['seed-preview-button','seed-create','seed-batch-preview','seed-batch-save'])$(id).hidden=!seedPermissions.edit;$('seed-ratio-save').hidden=!seedPermissions.publish;$('seed-section').hidden=false;$('seed-publisher').replaceChildren();for(const id of data.publishers){const o=node('option','運営用の投稿主体 '+id.slice(0,8));o.value=id;$('seed-publisher').append(o);}renderSeed();renderSeedCalendar();const stats=await rpc('seed_metrics');if((stamp!==seedStamp() || document.hidden))return;$('seed-metrics').textContent=`実登録 ${stats.real_registered_users} / UGC ${stats.ugc_posts} / 運営 ${stats.managed_posts} / 開発用公開 ${stats.synthetic_posts} / 運営上限比率 ${stats.max_seed_ratio}`;}\nfunction csvRows(text){\n if(text.length>100000)throw Error('CSVは100KBまでです。');\n const rows=[];let row=[],cell='',quoted=false;\n for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='\"'){if(quoted && text[i+1]==='\"'){cell+='\"';i++;}else if(quoted || cell==='')quoted=!quoted;else throw Error('CSVの引用符を確認してください。');}else if(!quoted && ch===','){row.push(cell);cell='';}else if(!quoted && (ch==='\\n' || ch==='\\r')){if(ch==='\\r' && text[i+1]==='\\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=ch;}\n if(quoted)throw Error('CSVの引用符が閉じていません。');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);\n return rows;\n}\nfunction parseSeedCSV(text){\n const rows=csvRows(text);\n const headers=rows.shift()?.map(v=>v.trim());const required=['key','name','species','breed','introduction','source'];if(!headers || headers.join(',')!==required.join(','))throw Error('ヘッダーは key,name,species,breed,introduction,source の順にしてください。');\n if(!rows.length || rows.length>20)throw Error('一度の登録は1〜20件です。');\n const items=rows.map(r=>{if(r.length!==6)throw Error('CSVの列数を確認してください。');const item=Object.fromEntries(required.map((key,i)=>[key,r[i].trim()]));if(!item.key || !item.name || !['dog','cat'].includes(item.species) || !item.source || item.name.length>40 || item.breed.length>100 || item.introduction.length>500 || item.source.length>500)throw Error('必須項目・文字数・dog/catを確認してください。');return item;});\n if(new Set(items.map(v=>v.key)).size!==items.length)throw Error('管理キーが重複しています。');return items;\n}\nfunction renderSeed(){\n releaseSeedPreviews();$('seed-list').replaceChildren();const selectedPets=new Set();const batch=node('div');const batchConfirm=node('input');batchConfirm.type='checkbox';const batchLabel=node('label');batchLabel.append(batchConfirm,node('span','選択したPetの全公開停止を確認する'));const batchStop=node('button','選択Petを一括停止');batchStop.addEventListener('click',()=>perform(async()=>{if(!batchConfirm.checked || !selectedPets.size)throw Error('対象Petを選択して停止を確認してください。');const stamp=seedStamp();await rpc('seed_stop',{p_pets:[...selectedPets],p_withdraw_rights:false});if((stamp===seedStamp() && !document.hidden))await refreshSeed();}));batchLabel.hidden=batchStop.hidden=!seedPermissions.stop;batch.append(batchLabel,batchStop);$('seed-list').append(batch);const q=$('seed-search').value.trim();\n for(const pet of seedSnapshot.pets.filter(p=>!q || (p.name+' '+p.key+' '+p.species).includes(q))){\n  const article=node('article');article.className='card';article.append(node('h2',pet.name),node('p',pet.species+' / '+pet.key),node('p',pet.active===false?'保管中・配信停止':'運営在庫として使用中'),node('p','内部Pet ID：'+pet.id),node('p','出典：'+pet.source),node('p',pet.rights_verified?'権利確認済み・期限 '+pet.rights_until:'権利未確認：下書きのみ'),node('p','更新版 '+pet.version+' / 最終担当 '+pet.updated_by));\n  const selected=node('input');selected.type='checkbox';const selectedLabel=node('label');selectedLabel.append(selected,node('span',pet.name+'を一括停止の対象にする'));selected.addEventListener('change',()=>selected.checked?selectedPets.add(pet.id):selectedPets.delete(pet.id));selectedLabel.hidden=!seedPermissions.stop;article.append(selectedLabel);\n  const copy=node('button','プロフィールを複製する前に確認');copy.hidden=!seedPermissions.edit;copy.addEventListener('click',()=>{const quote=v=>'\"'+String(v||'').replaceAll('\"','\"\"')+'\"';$('seed-csv').value='key,name,species,breed,introduction,source\\n'+[pet.key+'-copy-'+crypto.randomUUID().slice(0,8),pet.name,pet.species,pet.breed,pet.introduction,pet.source].map(quote).join(',');$('seed-preview').replaceChildren();seedItems=[];status('複製先の管理キー・名前・出典を確認し、新しくプレビューしてください。写真や権利承認は複製しません。');});article.append(copy);const edit=node('details');edit.append(node('summary','プロフィール編集・保管設定'));const edited={};for(const [field,label,value] of [['name','なまえ',pet.name],['breed','種類',pet.breed||''],['introduction','紹介文',pet.introduction||''],['source','内部出典',pet.source]]){const row=node('label',label);const input=node('input');input.value=value;edited[field]=input;row.append(input);edit.append(row);}const active=node('input');active.type='checkbox';active.checked=pet.active!==false;const activeLabel=node('label');activeLabel.append(active,node('span','運営在庫として利用する'));edit.append(activeLabel);const editConsent=node('input');editConsent.type='checkbox';const editLabel=node('label');editLabel.append(editConsent,node('span','変更後は公開停止・権利再審査になることを確認する'));edit.append(editLabel);const saveEdit=node('button','変更を保存して再審査へ');saveEdit.addEventListener('click',()=>perform(async()=>{if(!editConsent.checked)throw Error('公開停止と再審査を確認してください。');const stamp=seedStamp();await rpc('seed_edit',{p_pet:pet.id,p_version:pet.version,p_name:edited.name.value,p_breed:edited.breed.value,p_introduction:edited.introduction.value,p_source:edited.source.value,p_active:active.checked});if((stamp===seedStamp() && !document.hidden))await refreshSeed();}));edit.append(saveEdit);edit.hidden=!seedPermissions.edit;article.append(edit);\n  const file=node('input');file.type='file';file.accept='image/jpeg';file.multiple=true;file.setAttribute('aria-label',pet.name+'のJPEG素材');\n  const previews=node('div');previews.className='seed-previews';file.addEventListener('change',()=>{previews.replaceChildren();for(const f of [...file.files].slice(0,4)){if(f.type!=='image/jpeg' || f.size>20*1024*1024)continue;const url=URL.createObjectURL(f);seedPreviewURLs.push(url);const image=node('img');image.src=url;image.alt='配信前の素材プレビュー '+f.name;image.width=160;image.height=160;previews.append(image);} });article.append(previews);\n  const upload=node('button','選択JPEGを登録');upload.addEventListener('click',()=>perform(async()=>{\n   const files=[...file.files];if(!files.length || files.length>4 || files.some(f=>f.type!=='image/jpeg' || f.size>20*1024*1024) || files.reduce((n,f)=>n+f.size,0)>100*1024*1024)throw Error('JPEGを1〜4枚、1枚20MB・合計100MBまで選んでください。');\n   const stamp=seedStamp();\n   for(const f of files){const bytes=await f.arrayBuffer(),digest=new Uint8Array(await crypto.subtle.digest('SHA-256',bytes));const hex=Array.from(digest).map(x=>x.toString(16).padStart(2,'0')).join('');const id=hex.slice(0,8)+'-'+hex.slice(8,12)+'-'+hex.slice(12,16)+'-'+hex.slice(16,20)+'-'+hex.slice(20,32);if((stamp!==seedStamp() || document.hidden))return;\n    const p=await rpc('seed_begin_photo',{p_pet:pet.id,p_key:id,p_title:'JPEG '+hex.slice(0,8)});\n    if(p.state!=='ready'){const response=await fetch(config.url+'/storage/v1/object/family-originals/'+p.path,{method:'POST',headers:{apikey:config.anon_key,Authorization:'Bearer '+token,'Content-Type':'image/jpeg'},body:bytes,cache:'no-store',credentials:'omit'});if(!response.ok){const e=await response.json();if(![400,409].includes(response.status) || e.error!=='Duplicate')throw Error('素材の送信に失敗しました。同じファイルで再試行してください。');}if((stamp!==seedStamp() || document.hidden))return;await rpc('seed_finish_photo',{p_photo:p.id});}\n   }if((stamp===seedStamp() && !document.hidden)){file.value='';await refreshSeed();status('素材を非公開で登録しました。承認前には配信しません。');}\n  }));file.hidden=upload.hidden=!seedPermissions.edit;article.append(file,upload);\n  const chosen=[];const pics=node('div');for(const photo of pet.photos.filter(p=>p.state==='ready')){const label=node('label');const box=node('input');box.type='checkbox';box.addEventListener('change',()=>{const i=chosen.indexOf(photo.id);if(box.checked && i<0)chosen.push(photo.id);else if(i>=0)chosen.splice(i,1);});label.append(box,node('span',photo.title),node('code',photo.id));pics.append(label);\n   const preview=node('button','この素材をプレビュー');preview.addEventListener('click',()=>perform(()=>previewSeedPhoto(photo,pics)));pics.append(preview);\n   const record=node('details');record.append(node('summary','この画像の権利証跡'));const inputs={};for(const [key,label,value] of [['holder','権利者',photo.rights?.holder||''],['scope','使用範囲',photo.rights?.scope||''],['evidence','証跡の保管場所',photo.rights?.evidence||'']]){const row=node('label',label);const input=node('input');input.value=value;inputs[key]=input;row.append(input);record.append(row);}const until=node('input');until.type='datetime-local';until.setAttribute('aria-label','画像の権利期限');const allowed=node('input');allowed.type='checkbox';const rightsLabel=node('label');rightsLabel.append(allowed,node('span','この画像の権利証跡・掲載許可を確認する'));record.append(until,rightsLabel);const save=node('button','画像権利を確認して保存');save.addEventListener('click',()=>perform(async()=>{if(!allowed.checked || !until.value)throw Error('画像ごとの確認と期限を入力してください。');const stamp=seedStamp();await rpc('seed_photo_rights',{p_photo:photo.id,p_holder:inputs.holder.value,p_scope:inputs.scope.value,p_evidence:inputs.evidence.value,p_until:new Date(until.value).toISOString(),p_allowed:true});if((stamp===seedStamp() && !document.hidden))await refreshSeed();}));save.hidden=!seedPermissions.approve;record.append(save);if(photo.rights)record.append(node('p','確認担当 '+photo.rights.checked_by+' / '+photo.rights.checked_at+' / '+(photo.rights.allowed?'掲載許可あり':'撤回済み')));pics.append(record);const removeConfirm=node('input');removeConfirm.type='checkbox';const removeLabel=node('label');removeLabel.append(removeConfirm,node('span','この素材の公開停止・削除連動を確認する'));const remove=node('button','この素材を削除');remove.hidden=removeLabel.hidden=!seedPermissions.edit;remove.addEventListener('click',()=>perform(async()=>{if(!removeConfirm.checked)throw Error('削除連動を確認してください。');const stamp=seedStamp();await rpc('seed_delete_photo',{p_photo:photo.id,p_explicit:true});if(stamp===seedStamp()&&!document.hidden)await refreshSeed();}));pics.append(removeLabel,remove);if(photo.rights){const revoke=node('button','この素材の掲載権利を撤回');revoke.hidden=!seedPermissions.approve;revoke.addEventListener('click',()=>perform(async()=>{if(!removeConfirm.checked)throw Error('この素材の全公開停止を確認してください。');const stamp=seedStamp();await rpc('seed_photo_rights',{p_photo:photo.id,p_holder:photo.rights.holder,p_scope:photo.rights.scope,p_evidence:photo.rights.evidence,p_until:new Date(Date.now()+86400000).toISOString(),p_allowed:false});if(stamp===seedStamp()&&!document.hidden)await refreshSeed();}));pics.append(revoke);if(seedPermissions.approve)removeLabel.hidden=false;}}article.append(pics);\n  const body=node('textarea');body.maxLength=500;body.placeholder='Pet名義の投稿本文（任意・500字まで）';body.setAttribute('aria-label',pet.name+'の投稿本文');let draftKey=crypto.randomUUID();body.addEventListener('input',()=>draftKey=crypto.randomUUID());pics.addEventListener('change',()=>draftKey=crypto.randomUUID());\n  const draft=node('button','このPet名義で下書きを保存');draft.addEventListener('click',()=>perform(async()=>{if(chosen.length<1 || chosen.length>4)throw Error('写真を1〜4枚選んでください。');const stamp=seedStamp();await rpc('seed_draft',{p_pet:pet.id,p_photos:chosen,p_body:body.value,p_key:draftKey});if((stamp===seedStamp() && !document.hidden)){await refreshSeed();status('下書きを保存しました。');}}));body.hidden=draft.hidden=!seedPermissions.edit;article.append(body,draft);\n  for(const job of pet.jobs){const section=node('section');section.append(node('h3',job.state+' / 版 '+job.version),node('p',job.body));const rights=node('textarea');rights.placeholder='確認した権利・利用範囲・出典（10〜1000字）';rights.maxLength=1000;rights.setAttribute('aria-label','権利確認記録');const expiry=node('input');expiry.type='datetime-local';expiry.setAttribute('aria-label','権利期限');const consent=node('input');consent.type='checkbox';const confirmation=node('label');confirmation.append(consent,node('span','素材・本文・掲載権利を確認しました'));section.append(rights,expiry,confirmation);\n   const approve=node('button','権利確認して承認');approve.addEventListener('click',()=>perform(async()=>{if(!consent.checked || rights.value.trim().length<10 || !expiry.value)throw Error('権利記録・期限・確認を入力してください。');const stamp=seedStamp();await rpc('seed_approve',{p_job:job.id,p_version:job.version,p_rights_note:rights.value,p_rights_until:new Date(expiry.value).toISOString()});if((stamp===seedStamp() && !document.hidden))await refreshSeed();}));approve.hidden=job.state!=='draft'||!seedPermissions.approve;section.append(approve);\n   const when=node('input');when.type='datetime-local';when.setAttribute('aria-label','配信予定日時');const schedule=node('button','確認した内容で予約する');schedule.addEventListener('click',()=>perform(async()=>{if(!consent.checked || !when.value)throw Error('配信日時と確認を入力してください。');const stamp=seedStamp();await rpc('seed_schedule',{p_job:job.id,p_version:job.version,p_when:new Date(when.value).toISOString(),p_explicit:true});if((stamp===seedStamp() && !document.hidden)){await refreshSeed();status('予約しました。検証環境ではworkerの手動実行で処理します。');}}));when.hidden=schedule.hidden=job.state!=='approved'||!seedPermissions.schedule;section.append(when,schedule);\n   const immediate=node('button','確認した内容を今すぐ配信');immediate.hidden=job.state!=='approved'||!seedPermissions.schedule;immediate.addEventListener('click',()=>perform(async()=>{if(!consent.checked)throw Error('公開する素材・本文を確認してください。');const stamp=seedStamp();await rpc('seed_now',{p_job:job.id,p_version:job.version,p_explicit:true});if((stamp===seedStamp() && !document.hidden)){await refreshSeed();status('即時配信を受け付けました。検証worker処理後に表示されます。');}}));section.append(immediate);\n   const cancel=node('button','この予約・公開を取り消す');cancel.hidden=!['approved','scheduled','dispatching','published'].includes(job.state)||!seedPermissions.schedule;cancel.addEventListener('click',()=>perform(async()=>{if(!consent.checked)throw Error('対象の予約・公開取消を確認してください。');const stamp=seedStamp();await rpc('seed_cancel',{p_job:job.id,p_version:job.version,p_explicit:true});if((stamp===seedStamp() && !document.hidden))await refreshSeed();}));section.append(cancel);\n   const revise=node('button','本文を変更して再審査へ');revise.addEventListener('click',()=>perform(async()=>{if(!consent.checked)throw Error('変更と再審査を確認してください。');const stamp=seedStamp();await rpc('seed_revise',{p_job:job.id,p_version:job.version,p_photos:job.photos,p_body:body.value});if((stamp===seedStamp() && !document.hidden))await refreshSeed();}));revise.hidden=!seedPermissions.edit;section.append(revise);article.append(section);\n  }\n  const confirmStop=node('input');confirmStop.type='checkbox';const stopLabel=node('label');stopLabel.append(confirmStop,node('span','このPetの公開停止を確認する'));const stop=node('button','このPetの全公開を停止');stop.addEventListener('click',()=>perform(async()=>{if(!confirmStop.checked)throw Error('対象Petの停止を確認してください。');const stamp=seedStamp();await rpc('seed_stop',{p_pets:[pet.id],p_withdraw_rights:false});if((stamp===seedStamp() && !document.hidden))await refreshSeed();}));const withdraw=node('button','掲載権利を撤回して全配信を停止');withdraw.addEventListener('click',()=>perform(async()=>{if(!confirmStop.checked)throw Error('対象Petと権利撤回を確認してください。');const stamp=seedStamp();await rpc('seed_stop',{p_pets:[pet.id],p_withdraw_rights:true});if((stamp===seedStamp() && !document.hidden))await refreshSeed();}));stopLabel.hidden=stop.hidden=withdraw.hidden=!seedPermissions.stop;const history=node('button','このPetの画像権利履歴を表示');const historyBox=node('div');history.addEventListener('click',()=>perform(async()=>{const stamp=seedStamp();const rows=await rpc('seed_rights_history',{p_pet:pet.id});if(stamp!==seedStamp()||document.hidden)return;historyBox.replaceChildren();for(const row of rows)historyBox.append(node('p',row.recorded_at+' / '+row.operation+' / '+row.photo_id+' / '+row.rights.holder+' / '+row.rights.scope+' / '+row.rights.evidence+' / '+(row.rights.allowed?'許可':'撤回')));}));article.append(history,historyBox,stopLabel,stop,withdraw);$('seed-list').append(article);\n }\n}\n$('seed-refresh').addEventListener('click',()=>perform(refreshSeed));$('seed-search').addEventListener('input',()=>{if(seedSnapshot)renderSeed();});\n$('seed-preview-button').addEventListener('click',()=>perform(async()=>{seedItems=parseSeedCSV($('seed-csv').value);seedKey=crypto.randomUUID();$('seed-preview').replaceChildren();for(const item of seedItems)$('seed-preview').append(node('p',`${item.name} / ${item.species} / ${item.key} / 権利未確認：下書きのみ`));status('登録前のプレビューです。個別のPetログインは作成しません。');}));\n$('seed-create').addEventListener('click',()=>perform(async()=>{if(!seedItems.length || parseSeedCSV($('seed-csv').value).map(i=>JSON.stringify(i)).join()!==seedItems.map(i=>JSON.stringify(i)).join())throw Error('最新CSVのプレビューを確認してください。');const stamp=seedStamp();await rpc('seed_create',{p_publisher:$('seed-publisher').value,p_items:seedItems,p_key:seedKey});if((stamp===seedStamp() && !document.hidden)){seedItems=[];await refreshSeed();status('複数Petを同じ運営ログインで登録しました。');}}));\n\nlet seedBatchItems=[],seedBatchKey=crypto.randomUUID();\nfunction parseSeedPostCSV(text){const rows=csvRows(text);const headers=rows.shift();if(headers?.join(',')!=='pet_id,photo_ids,body,planned_at' || !rows.length || rows.length>20)throw Error('pet_id,photo_ids,body,planned_at の4列で1〜20件を入力してください。');return rows.map(row=>{if(row.length!==4)throw Error('投稿CSVの列数を確認してください。');const [pet_id,ids,body,time]=row;const photos=ids.split('|').map(v=>v.trim());const pet=seedSnapshot.pets.find(p=>p.id===pet_id.trim());if(!pet || !photos.length || photos.length>4 || new Set(photos).size!==photos.length || !photos.every(id=>pet.photos.some(p=>p.id===id && p.state==='ready')) || body.length>500)throw Error('Petと写真のひも付け・枚数・本文を確認してください。');const date=time?new Date(time):null;if(date && (!Number.isFinite(date.getTime()) || date<=new Date()))throw Error('予定日時には未来の日時を入力してください。');return {pet_id:pet.id,photos,body,planned_at:date?.toISOString()||null};});}\nfunction renderSeedCalendar(){$('seed-calendar').replaceChildren();const entries=seedSnapshot.pets.flatMap(p=>p.jobs.filter(j=>j.planned_at||j.scheduled_at).map(j=>({pet:p,job:j}))).sort((a,b)=>(a.job.scheduled_at||a.job.planned_at).localeCompare(b.job.scheduled_at||b.job.planned_at));for(const {pet,job} of entries)$('seed-calendar').append(node('p',(job.scheduled_at||job.planned_at)+' / '+pet.name+' / '+job.state+' / '+job.body));}\n$('seed-batch-preview').addEventListener('click',()=>perform(async()=>{seedBatchItems=parseSeedPostCSV($('seed-post-csv').value);seedBatchKey=crypto.randomUUID();$('seed-batch-list').replaceChildren();for(const item of seedBatchItems){const pet=seedSnapshot.pets.find(p=>p.id===item.pet_id);const row=node('article');row.append(node('p',pet.name+' / 写真 '+item.photos.length+'枚 / '+(item.planned_at||'日時未定')+' / '+item.body));for(const id of item.photos){const photo=pet.photos.find(p=>p.id===id);const preview=node('button',pet.name+'の一括投稿素材を確認 '+photo.title);preview.addEventListener('click',()=>perform(()=>previewSeedPhoto(photo,row)));row.append(preview);}$('seed-batch-list').append(row);}status('一括下書きの確認です。承認前には公開しません。');}));\n$('seed-batch-save').addEventListener('click',()=>perform(async()=>{const current=parseSeedPostCSV($('seed-post-csv').value);if(!seedBatchItems.length || JSON.stringify(current)!==JSON.stringify(seedBatchItems))throw Error('最新の一括プレビューを確認してください。');const stamp=seedStamp();await rpc('seed_draft_batch',{p_items:current,p_key:seedBatchKey});if((stamp===seedStamp() && !document.hidden)){seedBatchItems=[];$('seed-batch-list').replaceChildren();await refreshSeed();status('投稿を一括で下書き保存しました。個別に素材を確認・承認してください。');}}));\n\n$('seed-ratio-save').addEventListener('click',()=>perform(async()=>{const ratio=Number($('seed-ratio').value);if(!Number.isFinite(ratio)||ratio<0||ratio>1)throw Error('0〜1の上限比率を入力してください。');await rpc('seed_policy',{p_ratio:ratio});await refreshSeed();status('実UGC優先の運営上限比率を保存しました。');}));\n$('seed-audit-refresh').addEventListener('click',()=>perform(async()=>{const stamp=seedStamp();const rows=await rpc('seed_audit');if(stamp!==seedStamp()||document.hidden)return;$('seed-audit').replaceChildren();for(const row of rows)$('seed-audit').append(node('p',row.created_at+' / '+row.action+' / 担当 '+row.actor_id+' / Pet '+(row.pet_id||'設定')));}));\n\nasync function previewSeedPhoto(photo,container){\n const stamp=seedStamp();const response=await fetch(config.url+'/functions/v1/private-image?photo='+photo.id,{headers:{apikey:config.anon_key,Authorization:'Bearer '+token},cache:'no-store',credentials:'omit'});\n if(!response.ok||!response.headers.get('Content-Type')?.startsWith('image/'))throw Error('素材の権限・状態を再確認してください。');\n const reader=response.body.getReader();let chunks=[],total=0;\n try {while(true){const part=await reader.read();if(part.done)break;total+=part.value.byteLength;if(total>20*1024*1024||seedPreviewBytes+total>100*1024*1024)throw Error('プレビューの容量上限です。表示を更新してください。');chunks.push(part.value);}} finally {await reader.cancel();}\n if(stamp!==seedStamp()||document.hidden)return;\n const blob=new Blob(chunks,{type:response.headers.get('Content-Type')});seedPreviewBytes+=total;const url=URL.createObjectURL(blob);seedPreviewURLs.push(url);const image=node('img');image.src=url;image.alt='登録素材 '+photo.title;image.width=160;image.height=160;container.append(image);\n}\n"},"/console/admin.css":{"type":"text/css; charset=utf-8","body":"section{margin:40px 0;scroll-margin-top:20px}textarea{display:block;width:100%;max-width:100%;padding:12px;border:1px solid #b5a296;border-radius:10px;font:inherit}fieldset{border:1px solid #eadbd0;border-radius:12px;width:100%}.materials{display:flex;flex-wrap:wrap;gap:14px}.materials img{width:72px;height:72px;object-fit:cover}.materials label{max-width:160px}form>label{flex:1 1 240px}button{margin:4px}.card input,.card select{width:100%}.card .row{display:flex;gap:8px;align-items:center}.card .row input[type=checkbox]{width:20px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:10px;text-align:left;border-bottom:1px solid #e4d3c4}.scroll-table{overflow:auto}.post{margin:14px 0;padding:20px;background:white;border-radius:20px}.post img{width:90px;height:90px;object-fit:cover;border-radius:12px}.post p{white-space:pre-wrap}.error{color:#a32921}.rights{font-size:12px;padding:8px;background:#fff8f0}.rights label{margin-top:6px}\n"},"/console/base.css":{"type":"text/css; charset=utf-8","body":":root{--background:#FFFCF8;--accent:#F65359;--text:#292625;--radius:20px;--spacing:16px}*{box-sizing:border-box}body{margin:0;background:var(--background);color:var(--text);font:16px/1.7 system-ui,sans-serif}header{display:flex;justify-content:space-between;padding:24px 6vw;border-bottom:1px solid #e5d6c8}header span{letter-spacing:.18em;font-weight:700}a{color:var(--accent)}main{max-width:1020px;margin:auto;padding:36px 24px}.notice{padding:12px 6vw;background:#45312b;color:white;font-size:13px;margin:0}h1{font-size:clamp(32px,5vw,58px);line-height:1.35;margin:16px 0 24px}h2{font-size:26px}.eyebrow{color:var(--accent)}nav{display:flex;gap:12px;margin:30px 0;flex-wrap:wrap}button{background:var(--accent);color:white;border:0;border-radius:12px;padding:12px 18px;min-height:44px;font:inherit;cursor:pointer}button:disabled{opacity:.5}form{padding:20px;margin:20px 0;background:white;border-radius:var(--radius);display:flex;gap:var(--spacing);flex-wrap:wrap;align-items:end}label{display:block;font-size:14px}input:not([type=checkbox]),select{display:block;min-height:44px;padding:10px;border:1px solid #b5a296;border-radius:8px;max-width:100%;font:inherit}input[type=checkbox]{width:20px;height:20px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:20px}.card{background:white;border-radius:var(--radius);padding:16px;overflow:hidden}.card img{width:100%;aspect-ratio:1;object-fit:contain;border-radius:12px}.card h3{margin:6px 0}.muted,footer{font-size:13px;color:#6b5a51}.comparison{max-width:340px;aspect-ratio:9/16;background:white;border-radius:20px;padding:20px;text-align:center;margin:24px auto;display:flex;flex-direction:column;justify-content:space-around}.comparison img{width:100%;max-height:220px;object-fit:contain}#status{min-height:30px;border-left:3px solid var(--accent);padding:8px 14px}footer{margin-top:50px}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #45312b;outline-offset:3px}[hidden]{display:none!important}\n"},"/console/config.json":{"type":"application/json","body":"{\"url\": \"https://pbnimpqrthvznbwewtcf.supabase.co\", \"anon_key\": \"sb_publishable_yIFViOSjS7Qb6M2lNihRgA_Zk8n9M2m\"}"},"/console/security.js":{"type":"application/javascript; charset=utf-8","body":"'use strict';\nconst securityKinds={secret_probe:'秘密ファイル探索の疑い',path_traversal:'パス探索の疑い',injection_probe:'不正入力の疑い',auth_denied:'認証拒否',access_denied:'アクセス拒否',rate_limited:'回数制限',not_found:'404応答',method_denied:'未対応のメソッド',server_error:'サーバーエラー',profile_changed:'プロフィール変更',account_retirement:'退会の受付',operator_changed:'運営権限の変更',repeated_signals:'短時間の繰り返し検知'};\nconst securitySeverity={info:'情報',low:'低',medium:'中',high:'高',critical:'緊急'};\nconst securityOutcome={observed:'観測',denied:'拒否応答',limited:'回数制限',failed:'処理失敗',allowed:'許可'};\nconst securitySourceLabels={vercel:'Vercelサイト',app_audit:'アプリの監査記録','edge:security-collector':'ログ収集API','edge:private-image':'非公開画像API','edge:private-video':'非公開動画API','edge:public-image':'公開画像API','edge:public-video':'公開動画API','edge:shared-page':'共有ページAPI','edge:cloud-worker':'クラウド処理','edge:stock-worker':'運営投稿処理','edge:asset-ingest':'素材取り込み','edge:database-backup':'データベースバックアップ','edge:offsite-backup':'オフサイトバックアップ'};\nlet securityData=null,securityRows=[],securityCursor=null,securitySerial=0,securityTimer=null,securityView='overview';\nconst securityDrafts=new Map();\nconst sec=id=>document.getElementById(id);\nconst secNumber=n=>Number.isFinite(Number(n))?new Intl.NumberFormat('ja-JP').format(Number(n)):'—';\nfunction secTime(value,short=false){const date=new Date(value);return Number.isFinite(date.getTime())?new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',...(short?{}:{second:'2-digit'})}).format(date):'—';}\nfunction secNode(tag,text,className){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(className)e.className=className;return e;}\nfunction secBadge(value,kind='severity'){return secNode('span',kind==='severity'?(securitySeverity[value]||'情報'):value,'sec-badge '+(['info','low','medium','high','critical'].includes(value)?value:'neutral'));}\nfunction secEmpty(parent,text='この期間の記録はありません。'){parent.replaceChildren(secNode('p',text,'sec-empty'));}\nfunction secFilters(){return {p_hours:Number(sec('sec-hours').value),p_kind:sec('sec-kind').value||null,p_severity:sec('sec-severity').value||null,p_source:sec('sec-source').value||null,p_limit:50};}\nfunction clearSecurity(){securitySerial++;securityDrafts.clear();securityData=null;securityRows=[];securityCursor=null;if(securityTimer)clearTimeout(securityTimer);securityTimer=null;const root=sec('security-section');if(root)root.hidden=true;for(const id of ['sec-events','sec-incidents','sec-sources','sec-coverage','sec-types','sec-targets','sec-chart','sec-detail-body'])sec(id)?.replaceChildren();sec('sec-detail')?.close();document.body.classList.remove('security-console');sec('main-heading').hidden=false;sec('cancel-login').hidden=false;}\nfunction secSchedule(){if(securityTimer)clearTimeout(securityTimer);securityTimer=setTimeout(()=>{if(panel==='security'&&mfaComplete&&token&&!document.hidden&&sec('sec-auto').checked&&['overview','coverage'].includes(securityView)&&!sec('sec-detail').open&&!document.querySelector('#security-section textarea:focus'))perform(()=>refreshSecurity());else secSchedule();},30000);}\nasync function refreshSecurity(more=false){\n const serial=++securitySerial,stamp=generation;\n sec('security-section').hidden=false;document.body.classList.add('security-console');sec('main-heading').hidden=true;sec('cancel-login').hidden=true;\n sec('seed-section').hidden=true;sec('queue').hidden=true;sec('seed-refresh').hidden=true;sec('refresh').hidden=true;\n sec('server-health-refresh')?.closest('details')?.setAttribute('hidden','');\n sec('sec-connection').textContent='更新中';sec('sec-connection').className='sec-status-pill';\n const filters=secFilters();if(more&&securityCursor)Object.assign(filters,{p_before:securityCursor.occurred_at,p_before_id:securityCursor.id});\n try{\n  const data=await request('/rest/v1/rpc/mefrion_security_dashboard',filters,token,false);\n  if(serial!==securitySerial||stamp!==generation||!mfaComplete||panel!=='security')return;\n  securityData=data;const incoming=(data.events||[]).slice(0,50);const next=(data.events||[]).length>50;\n  securityRows=more?[...securityRows,...incoming.filter(row=>!securityRows.some(x=>x.id===row.id))]:incoming;\n  securityCursor=next?incoming.at(-1):null;\n  sec('sec-more').hidden=!securityCursor;sec('sec-message').textContent='';status('');\n  renderSecurity(data);const recent=(data.coverage||[]).some(row=>Date.now()-new Date(row.last_seen).getTime()<900000);sec('sec-connection').textContent=recent?'最近の受信を確認':(data.coverage||[]).length?'最近の受信なし（通信がない場合も含む）':'記録元からの受信待ち';sec('sec-connection').className='sec-status-pill'+(recent?' live':'');\n  secSchedule();\n }catch(error){\n  if(serial!==securitySerial||stamp!==generation)return;\n  sec('sec-connection').textContent='確認が必要';\n  if(error.status===403){sec('sec-message').textContent='二段階認証は完了しています。セキュリティ画面を開く運営権限の有効化をお待ちください。';status(sec('sec-message').textContent);}\n  else{sec('sec-message').textContent=error.name==='TimeoutError'?'更新に時間がかかっています。もう一度更新してください。':error instanceof TypeError?'通信できませんでした。接続を確認して更新してください。':error.message;}\n  if(!securityData){for(const id of ['sec-signals','sec-suspected','sec-denied','sec-open'])sec(id).textContent='—';sec('sec-chart').textContent='取得できる記録がまだありません。';}\n  secSchedule();\n }\n}\nfunction renderSecurity(data){\n const summary=data.summary||{};\n for(const [id,key]of [['sec-signals','signals'],['sec-suspected','suspected'],['sec-denied','denied']])sec(id).textContent=secNumber(summary[key]);\n sec('sec-open').textContent=secNumber(data.open_incidents);sec('sec-nav-incidents').textContent=secNumber(data.open_incidents);\n sec('sec-updated').textContent='最終更新 '+secTime(data.generated_at)+' JST';\n sec('sec-retention').textContent='収集開始 '+secTime(data.started_at)+' JST / 詳細30日・集計90日 / 集計からテストデータを除外（受信状態を除く）';\n renderSecurityChart(data.timeline||[],data.hours);\n renderSecurityBars(sec('sec-types'),data.types||[],row=>securityKinds[row.kind]||'その他');\n renderSecurityBars(sec('sec-targets'),data.targets||[],row=>row.target);\n const sources=sec('sec-sources');sources.replaceChildren();\n for(const row of data.sources||[]){const e=secNode('div',undefined,'sec-source-row');e.append(secNode('code',row.source_key),secNode('strong',secNumber(row.n)+'件'),secNode('time','最終 '+secTime(row.last_seen)));sources.append(e);}if(!sources.children.length)secEmpty(sources,'同じ接続元をまとめられる記録はまだありません。');\n renderSecurityEvents();renderSecurityIncidents(data.incidents||[]);renderSecurityCoverage(data);\n const limitations=sec('sec-limitations');limitations.replaceChildren();for(const text of data.limitations||[])limitations.append(secNode('li',text));\n const lost=(data.coverage||[]).reduce((n,r)=>n+Number(r.lost||0),0),omitted=(data.coverage||[]).reduce((n,r)=>n+Number(r.details_omitted||0),0);\n sec('sec-quality').textContent=lost||omitted?'報告された送信失敗 '+secNumber(lost)+'件 / 保存上限による詳細省略 '+secNumber(omitted)+'件。件数は収集できた記録の範囲です。':'記録の収集はベストエフォートです。到達前の遮断や、受信できなかった通信は件数に含みません。';\n}\nfunction renderSecurityBars(parent,rows,label){parent.replaceChildren();if(!rows.length){secEmpty(parent);return;}const max=Math.max(1,...rows.map(r=>Number(r.count)));for(const row of rows){const item=secNode('div',undefined,'sec-bar-row');item.append(secNode('span',label(row)),secNode('strong',secNumber(row.count)));const track=secNode('div',undefined,'sec-bar-track'),fill=secNode('div',undefined,'sec-bar-fill');fill.style.width=(Math.max(0,Number(row.count))/max*100)+'%';track.append(fill);item.append(track);parent.append(item);}}\nfunction renderSecurityChart(rows,hours){\n const root=sec('sec-chart');root.replaceChildren();\n if(!rows.length){root.textContent='この期間に収集したシグナルはありません。';root.setAttribute('aria-label','記録0件。未収集の通信は含みません。');return;}\n const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 900 230');svg.setAttribute('aria-hidden','true');\n const make=(tag,attrs,text)=>{const e=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,String(v));if(text!==undefined)e.textContent=text;svg.append(e);return e;};\n const interval=hours>168?86400000:3600000,end=Math.floor(Date.now()/interval)*interval,start=end-(hours>168?Math.ceil(hours/24)-1:hours-1)*interval;\n const lookup=new Map(rows.map(r=>[Math.floor(new Date(r.at).getTime()/interval)*interval,r]));const points=[];\n for(let t=start;t<=end;t+=interval)points.push({t,n:Number(lookup.get(t)?.signals||0),s:Number(lookup.get(t)?.suspected||0)});\n const maximum=Math.max(1,...points.map(p=>p.n)),x=i=>45+i/(Math.max(1,points.length-1))*840,y=n=>190-n/maximum*160;\n for(let i=0;i<=4;i++){const yy=190-i*40;make('line',{x1:45,x2:885,y1:yy,y2:yy,stroke:'#e7edf5','stroke-dasharray':'3 4'});make('text',{x:32,y:yy+4,'text-anchor':'end',fill:'#8291a7','font-size':10},secNumber(Math.round(maximum*i/4)));}\n make('polygon',{points:`45,190 ${points.map((p,i)=>x(i)+','+y(p.n)).join(' ')} 885,190`,fill:'#edf1ff'});\n make('polyline',{points:points.map((p,i)=>x(i)+','+y(p.n)).join(' '),fill:'none',stroke:'#5776dc','stroke-width':2.5});\n make('polyline',{points:points.map((p,i)=>x(i)+','+y(p.s)).join(' '),fill:'none',stroke:'#15b5a1','stroke-width':2});\n for(const i of [0,Math.floor((points.length-1)/3),Math.floor((points.length-1)*2/3),points.length-1]){const d=new Date(points[i].t);const label=new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',...(hours>24?{month:'2-digit',day:'2-digit'}:{hour:'2-digit',minute:'2-digit'})}).format(d);make('text',{x:x(i),y:219,'text-anchor':i===0?'start':i===points.length-1?'end':'middle',fill:'#8291a7','font-size':10},label);}\n root.append(svg);root.setAttribute('aria-label',rows.map(r=>secTime(r.at,true)+' 記録'+secNumber(r.signals)+'件・攻撃の疑い'+secNumber(r.suspected||0)+'件').join('。'));\n}\nfunction renderSecurityEvents(){const body=sec('sec-events');body.replaceChildren();for(const row of securityRows){const tr=secNode('tr');tr.append(secNode('td',secTime(row.occurred_at)),secNode('td',securityKinds[row.kind]||'その他'));const severity=secNode('td');severity.append(secBadge(row.severity));tr.append(severity);const target=secNode('td');target.append(secNode('code',row.target));tr.append(target,secNode('td',(securityOutcome[row.outcome]||'観測')+' · '+row.status));const detail=secNode('td'),button=secNode('button','詳細');button.type='button';button.addEventListener('click',()=>showSecurityDetail(row));detail.append(button);tr.append(detail);body.append(tr);}if(!securityRows.length){const tr=secNode('tr'),td=secNode('td','この条件の記録はありません。','sec-empty');td.colSpan=6;tr.append(td);body.append(tr);}sec('sec-event-count').textContent=secNumber(securityRows.length)+'件を表示 / フィルターはログ一覧に適用されます。';}\nfunction showSecurityDetail(row){const dl=sec('sec-detail-body');dl.replaceChildren();for(const[key,value]of [['記録ID',row.id],['記録時刻',secTime(row.occurred_at)+' JST'],['種類',securityKinds[row.kind]||row.kind],['重要度',securitySeverity[row.severity]||'情報'],['応答',row.status+' / '+(securityOutcome[row.outcome]||'観測')],['対象',row.target],['記録元',securitySourceLabels[row.source]||row.source],['接続元ID',row.source_key==='unavailable'?'取得できず':row.source_key],['地域（参考）',row.country||'不明'],['照合用リクエストID',row.request_id||'なし']])dl.append(secNode('dt',key),secNode('dd',String(value)));sec('sec-detail').showModal();}\nfunction renderSecurityIncidents(rows){const root=sec('sec-incidents');root.replaceChildren();for(const row of rows){const card=secNode('article',undefined,'sec-incident'),head=secNode('div',undefined,'sec-incident-head');head.append(secBadge(row.severity),secNode('h3',securityKinds[row.kind]||'繰り返し検知'));card.append(head,secNode('p',secNumber(row.events)+'件 / '+row.source_key+' / 更新 '+secTime(row.updated_at)),secNode('p','状態：'+({open:'未対応',acknowledged:'確認中',resolved:'対応済み'}[row.state]||row.state)));const note=secNode('textarea');note.value=securityDrafts.get(row.id)??row.note??'';note.maxLength=400;note.addEventListener('input',()=>securityDrafts.set(row.id,note.value));note.placeholder='対応メモ（秘密情報や個人情報は書かない）';note.setAttribute('aria-label','インシデントの対応メモ');card.append(note);const actions=secNode('div',undefined,'sec-incident-controls');for(const [state,label]of [['acknowledged','確認中にする'],['resolved','対応済みにする'],['open','未対応に戻す']]){const button=secNode('button',state===row.state?'メモを保存':label);button.type='button';button.addEventListener('click',()=>perform(async()=>{try{await request('/rest/v1/rpc/mefrion_security_incident_update',{p_id:row.id,p_state:state,p_version:row.version,p_note:note.value},token,false);securityDrafts.delete(row.id);await refreshSecurity();sec('sec-message').textContent='対応状態を保存しました。';}catch(error){sec('sec-message').textContent=error.status===409?'別の更新があります。更新ボタンで再取得してください。':error.message;}}));actions.append(button);}card.append(actions);root.append(card);}if(!rows.length)secEmpty(root,'確認対象のインシデントはありません。');}\nfunction renderSecurityCoverage(data){const root=sec('sec-coverage');root.replaceChildren();const actual=new Map((data.coverage||[]).map(row=>[row.source,row]));for(const [name,label]of Object.entries(securitySourceLabels)){const row=actual.get(name),item=secNode('div',undefined,'sec-coverage-row'),text=secNode('div');text.append(secNode('strong',label));const last=row?'最終受信 '+secTime(row.last_seen)+' JST / シグナル '+secNumber(row.accepted)+'件（テスト含む）':'配備後の受信待ち。アクセスがない場合も受信待ちになります。';text.append(secNode('small',last));if(row?.lost)text.append(secNode('small','送信できなかった記録 '+secNumber(row.lost)+'件'));item.append(text,secBadge(!row?'受信待ち':Date.now()-new Date(row.last_seen).getTime()<900000?'最近の受信あり':'最近の受信なし','label'));root.append(item);}}\nfunction securityCSV(rows){const cell=value=>{let s=String(value??'');if(/^[=+\\-@\\t\\r]/.test(s))s=\"'\"+s;return '\"'+s.replace(/\"/g,'\"\"')+'\"';};const fields=['id','occurred_at','source','kind','severity','outcome','status','target','source_key','country','request_id'];return '\\uFEFF'+[fields.map(cell).join(','),...rows.map(row=>fields.map(k=>cell(row[k])).join(','))].join('\\r\\n');}\nasync function exportSecurity(){if(!mfaComplete||!token)throw Error('運営アカウントでログインしてください。');const stamp=generation,filters={...secFilters(),p_limit:100};const rows=[];for(let i=0;i<10;i++){const data=await request('/rest/v1/rpc/mefrion_security_dashboard',filters,token,false);if(stamp!==generation)return;const batch=(data.events||[]).slice(0,100);rows.push(...batch);if((data.events||[]).length<=100||!batch.length)break;filters.p_before=batch.at(-1).occurred_at;filters.p_before_id=batch.at(-1).id;}const blob=new Blob([securityCSV(rows)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=secNode('a');link.href=url;link.download='MEFRION-security-'+new Date().toISOString().slice(0,10)+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);sec('sec-message').textContent=secNumber(rows.length)+'件を書き出しました（最大1,000件）。';}\nfunction secShowView(view){securityView=view;for(const el of document.querySelectorAll('[data-sec-panel]'))el.hidden=el.dataset.secPanel!==view;for(const button of document.querySelectorAll('[data-sec-view]'))button.classList.toggle('active',button.dataset.secView===view);}\nif(document.getElementById('security-section')){\n for(const [value,label] of Object.entries(securitySourceLabels)){if(!Array.from(sec('sec-source').options).some(option=>option.value===value)){const option=secNode('option',label);option.value=value;sec('sec-source').append(option);}}\n sec('sec-refresh').addEventListener('click',()=>perform(()=>refreshSecurity()));sec('sec-more').addEventListener('click',()=>perform(()=>refreshSecurity(true)));sec('sec-export').addEventListener('click',()=>perform(exportSecurity));sec('sec-detail-close').addEventListener('click',()=>sec('sec-detail').close());\n for(const id of ['sec-hours','sec-kind','sec-severity','sec-source'])sec(id).addEventListener('change',()=>perform(()=>refreshSecurity()));\n for(const button of document.querySelectorAll('[data-sec-view]'))button.addEventListener('click',()=>secShowView(button.dataset.secView));\n sec('security-nav').addEventListener('click',()=>perform(async()=>{panel='security';await refreshSecurity();}));\n sec('reports-nav').addEventListener('click',()=>perform(async()=>{panel='reports';clearSecurity();sec('server-health-refresh')?.closest('details')?.removeAttribute('hidden');sec('seed-refresh').hidden=false;sec('refresh').hidden=false;await refresh();}));\n}\n"},"/console/security.css":{"type":"text/css; charset=utf-8","body":"#security-section{--ink:#172b43;--muted:#61728b;--line:#e4eaf1;--blue:#3259d6;--mint:#11b4a0;font-family:ui-sans-serif,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;color:var(--ink);font-size:14px;text-align:left;line-height:1.6}body.security-console{background:#f3f6fb}body.security-console>header{display:none}body.security-console>main{max-width:1480px;padding:16px;margin:auto}#security-section *{box-sizing:border-box}#security-section button,#security-section select,#security-section input,#security-section textarea{font:inherit}#security-section button{cursor:pointer;border:1px solid #d8e0ed;background:white;color:var(--ink);border-radius:9px;padding:9px 15px;min-height:42px;margin:0}#security-section button:hover{background:#edf3ff;border-color:#b8c9ed}#security-section button:focus-visible,#security-section select:focus-visible{outline:3px solid #98b0ff;outline-offset:2px}#security-section button:disabled{cursor:wait;opacity:.55}#security-section h1,#security-section h2,#security-section h3,#security-section p{margin:0}#security-section h1{font-size:30px;letter-spacing:-.04em;color:var(--ink)}#security-section h2{font-size:16px;font-weight:700;color:var(--ink);margin-bottom:5px}#security-section h3{font-size:14px;color:var(--ink)}#security-section a{color:#3259d6;text-decoration:none}.sec-layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:0;border:1px solid var(--line);border-radius:18px;overflow:clip;min-height:800px;background:#f4f7fb}.sec-sidebar{background:#12233b;color:#c6d4e9;padding:30px 18px;position:relative;display:flex;flex-direction:column}.sec-wordmark{display:flex;align-items:center;flex-wrap:wrap;gap:9px;color:#fff!important;font-size:17px;font-weight:750;letter-spacing:.025em}.sec-shield{display:grid;place-items:center;background:#13b8a6;color:#082e31;width:33px;height:36px;border-radius:9px 9px 15px 15px}.sec-wordmark-small{display:block;margin-left:43px;font-size:9px;letter-spacing:.23em;color:#8fa7c5}.sec-side-caption{margin-top:39px!important;margin-bottom:15px!important;font-size:10px;letter-spacing:.12em;color:#8ba0bd}.sec-sidebar nav{display:flex;gap:7px;flex-direction:column}.sec-sidebar nav button{border:0!important;background:transparent!important;color:#b5c7df!important;text-align:left;padding:12px 13px!important}.sec-sidebar nav button.active{background:#263c59!important;color:white!important}.sec-sidebar nav button span{float:right;background:#344d6e;border-radius:6px;min-width:23px;text-align:center;font-size:12px}.sec-side-bottom{font-size:11px;margin-top:auto;padding-top:80px}.sec-side-bottom p{font-size:10px;color:#92a9c4;margin-top:7px!important}.sec-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#29cfb5;margin-right:6px}.sec-main{min-width:0;padding:30px}.sec-top{display:flex;justify-content:space-between;gap:20px;align-items:center;padding:0;background:none;border:0;box-shadow:none}.sec-eyebrow{font-size:10px;letter-spacing:.2em;color:#596d8c}.sec-sub{font-size:12px;color:var(--muted);margin-top:4px!important}.sec-controls{display:flex;align-items:center;gap:8px}.sec-controls select,.sec-filters select{border:1px solid #d8e0ed;border-radius:9px;padding:9px;background:white;color:var(--ink);width:auto;min-height:42px}.sec-statusline{display:flex;gap:12px;align-items:center;flex-wrap:wrap;font-size:11px;color:var(--muted);margin:23px 0}.sec-statusline label{margin:0 0 0 auto;display:flex;gap:7px;align-items:center}.sec-statusline input{width:15px;height:15px;margin:0}.sec-status-pill,.sec-badge{display:inline-flex;align-items:center;border-radius:20px;padding:3px 9px;font-size:11px;font-weight:600;background:#e7edf5;color:#4e6079}.sec-status-pill.live{background:#dcf6ef;color:#087363}.sec-badge.high,.sec-badge.critical{background:#fff0ef;color:#ac3844}.sec-badge.medium{background:#fff4dc;color:#8b6411}.sec-badge.low{background:#edf0ff;color:#4a5ab5}.sec-badge.info,.sec-badge.neutral{background:#edf1f6;color:#5d6a7b}.sec-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:0 0 20px}.sec-metrics article{background:white;border:1px solid var(--line);padding:18px;border-radius:12px}.sec-metrics article>span{font-size:11px;color:var(--muted)}.sec-metrics strong{display:block;font-variant-numeric:tabular-nums;font-size:31px;letter-spacing:-.04em;font-weight:750;color:var(--ink);margin:8px 0 3px}.sec-metrics article:nth-child(2) strong{color:#bc5661}.sec-metrics article:nth-child(3) strong{color:var(--blue)}.sec-metrics small{font-size:9px;color:var(--muted);display:block}.sec-card{border:1px solid var(--line);background:white;border-radius:12px;padding:22px;margin:0 0 18px}.sec-card p{font-size:12px;color:var(--muted)}.sec-card-head{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:20px}.sec-legend{display:flex;gap:12px;font-size:10px;white-space:nowrap}.sec-legend span:first-child{color:#4869dd}.sec-legend span+span{color:#18af9d}.sec-chart{height:230px;width:100%;display:flex;align-items:center;justify-content:center;color:var(--muted)}.sec-chart svg{width:100%;height:100%}.sec-grid-two{display:grid;grid-template-columns:1fr 1fr;gap:18px}.sec-breakdown{margin-top:18px}.sec-bar-row{display:grid;grid-template-columns:minmax(0,1fr) 48px;gap:6px 12px;align-items:center;margin-top:13px;font-size:11px}.sec-bar-row strong{text-align:right;font-variant-numeric:tabular-nums;color:var(--ink);font-size:12px}.sec-bar-track{height:5px;background:#eef2f8;border-radius:5px;grid-column:1/-1;overflow:hidden}.sec-bar-fill{height:100%;background:#6684e3;border-radius:5px}.sec-breakdown .sec-bar-row:nth-child(2n) .sec-bar-fill{background:#51bbaa}.sec-source-row{display:grid;grid-template-columns:1fr auto auto;gap:20px;padding:13px 0;border-bottom:1px solid #edf1f6;font-size:11px}.sec-source-row code{font-size:11px}.sec-source-row:last-child{border:0}.sec-filters{display:flex;gap:12px;flex-wrap:wrap;margin:0 0 18px}.sec-filters label{display:flex;flex-direction:column;gap:5px;color:var(--muted);font-size:11px;min-width:120px;margin:0}.sec-table-wrap{overflow-x:auto}#security-section table{border-collapse:collapse;width:100%;min-width:680px;font-size:11px}#security-section th{font-weight:600;color:var(--muted);text-align:left;background:#f6f8fc;padding:11px;white-space:nowrap}#security-section td{padding:13px 11px;border-bottom:1px solid var(--line);vertical-align:middle}#security-section td button{padding:4px 10px;min-height:34px}#security-section td code{font-size:10px;overflow-wrap:anywhere}.sec-footnote{font-size:10px!important;color:var(--muted);margin-top:12px!important}.sec-empty{padding:35px 10px;text-align:center;color:var(--muted);font-size:12px}.sec-incident{padding:20px 0;border-bottom:1px solid var(--line)}.sec-incident:first-child{padding-top:0}.sec-incident-head{display:flex;align-items:center;gap:10px}.sec-incident p{margin-top:8px!important}.sec-incident-controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:12px}.sec-incident textarea{min-height:60px;width:100%;border:1px solid #d8e0ed;border-radius:8px;padding:10px;color:var(--ink);background:white;margin-top:12px}.sec-coverage-row{display:flex;justify-content:space-between;gap:15px;padding:16px 0;border-bottom:1px solid var(--line)}.sec-coverage-row small{display:block;font-size:10px;color:var(--muted);margin-top:4px}.sec-coverage-static{margin-top:25px;display:grid;grid-template-columns:1fr 1fr;gap:16px}.sec-coverage-static article{border:1px solid var(--line);border-radius:10px;padding:17px}.sec-coverage-static .sec-badge{margin:8px 0}.sec-coverage-static a{font-size:11px;display:inline-block;margin-top:12px}.sec-footer{font-size:10px;color:var(--muted);padding:0;margin-top:22px;background:none;border:0;display:block}.sec-footer span{display:block;margin-top:6px}#sec-message:not(:empty){padding:12px 16px;margin-bottom:18px;border-radius:10px;background:#fff4da;color:#6f530c;font-size:12px}#sec-detail{max-width:600px;width:calc(100% - 32px);border:1px solid var(--line);border-radius:16px;padding:24px;color:var(--ink);background:#fff}#sec-detail::backdrop{background:#0b1c35aa}.sec-detail-head{display:flex;align-items:center;justify-content:space-between}#sec-detail-body{display:grid;grid-template-columns:110px 1fr;gap:12px;font-size:12px;margin-top:24px}#sec-detail-body dt{color:var(--muted)}#sec-detail-body dd{margin:0;overflow-wrap:anywhere;font-family:ui-monospace,monospace}#sec-detail p{font-size:11px;color:var(--muted)}.sec-sr{position:absolute;clip:rect(0,0,0,0);width:1px;height:1px;overflow:hidden}#security-section [hidden]{display:none!important}@media(max-width:1100px){.sec-layout{grid-template-columns:180px minmax(0,1fr)}.sec-main{padding:22px}.sec-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.sec-legend{display:none}}@media(max-width:720px){body.security-console>main{padding:8px}.sec-layout{display:block;border-radius:12px}.sec-sidebar{padding:16px}.sec-wordmark-small,.sec-side-caption,.sec-side-bottom{display:none!important}.sec-sidebar nav{flex-direction:row;overflow-x:auto;margin-top:16px}.sec-sidebar nav button{white-space:nowrap;min-width:100px}.sec-main{padding:18px 12px}.sec-top{align-items:flex-start;flex-direction:column}.sec-top h1{font-size:25px}.sec-controls{width:100%}.sec-controls select{flex:1}.sec-statusline label{margin-left:0}.sec-metrics{gap:10px}.sec-metrics article{padding:14px}.sec-metrics strong{font-size:27px}.sec-metrics small{min-height:27px}.sec-grid-two,.sec-coverage-static{grid-template-columns:1fr}.sec-card{padding:16px}.sec-card-head{align-items:flex-start;flex-wrap:wrap}.sec-chart{height:180px}.sec-source-row{grid-template-columns:1fr auto;gap:6px}.sec-source-row time{grid-column:1/-1}.sec-filters label{min-width:calc(50% - 8px)}.sec-filters select{width:100%}}\nbody.security-console main>.notice,body.security-console main>details,body.security-console #email-login-toggle{display:none}body.security-console #status:empty{display:none}body.security-console #session{display:flex;justify-content:flex-end;gap:8px;align-items:center;margin:0 0 14px}body.security-console #session[hidden]{display:none}body.security-console #session>button{border:1px solid #d8e0ed;background:white;color:#344963;font:600 12px ui-sans-serif,-apple-system,sans-serif;padding:8px 14px;border-radius:9px;margin:0;min-height:38px}body.security-console #session>button:hover{background:#e8effa}body.security-console #session>#logout{color:#a24454}\n@media(max-width:720px){.sec-sidebar nav{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:14px 0 0;padding:0;overflow:visible}.sec-sidebar nav button{min-width:0;white-space:normal;text-align:left;padding:9px 12px}.sec-sidebar{min-height:0}}\n"},"/console/security":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"ja\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"mefrion-config\" content=\"/console/config.json\"><title>セキュリティ監視｜MEFRION</title><link rel=\"stylesheet\" href=\"/console/base.css\"><link rel=\"stylesheet\" href=\"/console/admin.css\"><script src=\"/console/cloud.js\" defer></script><script src=\"/console/seed.js\" defer></script><link rel=\"stylesheet\" href=\"/console/security.css\"><script src=\"/console/security.js\" defer></script><body data-console-panel=\"security\"><header><span>MEFRION / クラウド運営管理</span><a href=\"/console/\">一括管理へ</a></header><main><h1 id=\"main-heading\">運営管理</h1><p class=\"notice\">MEFRIONの運営管理。運営権限と認証アプリのMFAが必要です。利用者の家族アルバム原本と通報者の情報は取得しません。運営素材は担当権限で管理します。権限を付与された担当者だけが利用できます。</p><form id=\"login\"><label>運営アカウントのメール<input id=\"email\" type=\"email\" autocomplete=\"username\" required></label><label>パスワード<input id=\"password\" type=\"password\" autocomplete=\"current-password\" required></label><button>ログイン</button></form><button id=\"email-login-toggle\" type=\"button\">メールのコードでログイン・登録</button><form id=\"email-login\" hidden><label>運営アカウントのメール<input id=\"otp-email\" type=\"email\" autocomplete=\"email\" required></label><p>初めての方はMEFRIONアカウントが作成されます。登録だけでは運営権限は付与されません。</p><label><input id=\"otp-consent\" type=\"checkbox\" required>18歳以上で、<a href=\"/terms\" target=\"_blank\" rel=\"noopener\">利用条件</a>と<a href=\"/privacy\" target=\"_blank\" rel=\"noopener\">プライバシーポリシー</a>を確認しました</label><button>確認コードを送る</button></form><form id=\"email-verify\" hidden><label>メールの確認コード<input id=\"email-code\" type=\"text\" inputmode=\"numeric\" pattern=\"[0-9]{6,8}\" maxlength=\"8\" autocomplete=\"one-time-code\" required></label><button>コードで続ける</button></form><section id=\"enroll\" hidden><h2>認証アプリの登録</h2><p>MEFRION運営アカウントに認証アプリを登録します。登録だけで運営権限は付与されません。コード・秘密は他の人へ送らないでください。</p><button id=\"start-enroll\">本人が認証アプリ登録を開始する</button><div id=\"enroll-instructions\" hidden><p>認証アプリで新しい項目を追加し、名前を「MEFRION operator」にして、次の設定キーを登録してください。以前のSupabase用とは別の6桁が表示されます。</p><code id=\"enroll-secret\"></code><button id=\"copy-enroll-key\" type=\"button\">設定キーをコピー</button></div></section><form id=\"mfa\" hidden novalidate><label>認証アプリの6桁コード<input id=\"code\" type=\"password\" inputmode=\"numeric\" pattern=\"[0-9]{6}\" maxlength=\"12\" aria-describedby=\"mfa-help status\" autocomplete=\"one-time-code\" required></label><button type=\"submit\">この6桁で確認する</button><p id=\"mfa-feedback\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\"></p><p id=\"mfa-help\">入力したあと、このボタンを押してください。今回「MEFRION operator」として追加した認証アプリの6桁を使います。メールの確認コード・以前のSupabase用とは別です。</p></form><button id=\"restart-enroll\" type=\"button\" hidden>認証アプリを登録し直す</button><button id=\"cancel-login\">ログインを取り消す</button><details><summary>接続に困ったとき</summary><button id=\"check-connection\" type=\"button\">接続を確認</button><p>メールの送信やアカウントの作成は行いません。</p></details><p id=\"status\" role=\"status\" aria-live=\"polite\"></p><div id=\"session\" hidden><button id=\"security-nav\" type=\"button\">セキュリティ</button><button id=\"reports-nav\" type=\"button\">通報</button><details><summary>サーバー稼働状況</summary><button id=\"server-health-refresh\">現在の状態を見る</button><pre id=\"server-health-output\"></pre></details><button id=\"seed-refresh\">運営Pet・下書きを取得</button><button id=\"refresh\">最新の通報を取得</button><button id=\"logout\">ログアウト</button></div><section id=\"security-section\" hidden aria-label=\"セキュリティ監視\">\n <div class=\"sec-layout\"><aside class=\"sec-sidebar\"><a class=\"sec-wordmark\" href=\"/console/security\"><span class=\"sec-shield\">M</span> MEFRION<span class=\"sec-wordmark-small\">SECURITY</span></a><p class=\"sec-side-caption\">運営ワークスペース</p><nav aria-label=\"監視メニュー\"><button data-sec-view=\"overview\" class=\"active\">◈ 概要</button><button data-sec-view=\"events\">≋ 検知ログ</button><button data-sec-view=\"incidents\">⚑ インシデント <span id=\"sec-nav-incidents\">—</span></button><button data-sec-view=\"coverage\">◎ 監視範囲</button></nav><div class=\"sec-side-bottom\"><span class=\"sec-dot\"></span> 運営アカウント限定<p>二段階認証で保護されています</p></div></aside>\n <div class=\"sec-main\"><header class=\"sec-top\"><div><p class=\"sec-eyebrow\">SECURITY OPERATIONS</p><h1>セキュリティ</h1><p class=\"sec-sub\">起きていることを、記録から確かめる。</p></div><div class=\"sec-controls\"><label class=\"sec-sr\" for=\"sec-hours\">集計期間</label><select id=\"sec-hours\"><option value=\"24\">直近24時間</option><option value=\"168\">直近7日間</option><option value=\"720\">直近30日間</option></select><button id=\"sec-refresh\" type=\"button\">↻ 更新</button></div></header>\n <div class=\"sec-statusline\"><span id=\"sec-connection\" class=\"sec-status-pill\">接続を確認中</span><span id=\"sec-updated\">—</span><label><input id=\"sec-auto\" type=\"checkbox\" checked>概要を30秒ごとに更新</label></div>\n <div id=\"sec-message\" role=\"status\" aria-live=\"polite\"></div>\n <div class=\"sec-view\" data-sec-panel=\"overview\"><div class=\"sec-metrics\"><article><span>記録したシグナル</span><strong id=\"sec-signals\">—</strong><small>通常のエラー・監査記録も含む</small></article><article><span>攻撃の疑い</span><strong id=\"sec-suspected\">—</strong><small>探索・不正入力のパターン検知</small></article><article><span>拒否・制限の応答</span><strong id=\"sec-denied\">—</strong><small>401 / 403 / 404 / 405 / 429など</small></article><article><span>未対応のインシデント</span><strong id=\"sec-open\">—</strong><small>全期間・対応待ちの件数</small></article></div>\n <section class=\"sec-card\"><div class=\"sec-card-head\"><div><h2>シグナルの推移</h2><p>記録件数と、攻撃が疑われるパターン</p></div><div class=\"sec-legend\"><span>● 記録件数</span><span>● 攻撃の疑い</span></div></div><div id=\"sec-chart\" class=\"sec-chart\" role=\"img\" aria-label=\"集計結果の取得待ち\"></div><p class=\"sec-footnote\">時間単位の集計です。過去の未収集データは表示しません。</p></section>\n <div class=\"sec-grid-two\"><section class=\"sec-card\"><h2>検知の内訳</h2><div id=\"sec-types\" class=\"sec-breakdown\"></div></section><section class=\"sec-card\"><h2>対象になった場所</h2><div id=\"sec-targets\" class=\"sec-breakdown\"></div></section></div>\n <section class=\"sec-card\"><div class=\"sec-card-head\"><div><h2>繰り返し観測した接続元</h2><p>匿名化した識別子。個人や攻撃者の特定ではありません。</p></div></div><div id=\"sec-sources\"></div></section></div>\n <section class=\"sec-view sec-card\" data-sec-panel=\"events\" hidden><div class=\"sec-card-head\"><div><h2>検知ログ</h2><p>詳細を選んで、応答結果と記録IDを確認できます。</p></div><button id=\"sec-export\" type=\"button\">CSVを書き出す</button></div><div class=\"sec-filters\"><label>種類<select id=\"sec-kind\"><option value=\"\">すべての種類</option><option value=\"secret_probe\">秘密ファイル探索の疑い</option><option value=\"path_traversal\">パス探索の疑い</option><option value=\"injection_probe\">不正入力の疑い</option><option value=\"auth_denied\">認証拒否</option><option value=\"access_denied\">アクセス拒否</option><option value=\"rate_limited\">回数制限</option><option value=\"not_found\">404応答</option><option value=\"method_denied\">未対応のメソッド</option><option value=\"account_retirement\">退会の受付</option><option value=\"server_error\">サーバーエラー</option><option value=\"operator_changed\">運営権限の変更</option></select></label><label>重要度<select id=\"sec-severity\"><option value=\"\">すべて</option><option value=\"critical\">緊急</option><option value=\"high\">高</option><option value=\"medium\">中</option><option value=\"low\">低</option><option value=\"info\">情報</option></select></label><label>記録元<select id=\"sec-source\"><option value=\"\">すべて</option><option value=\"vercel\">Vercelサイト</option><option value=\"edge:private-image\">非公開画像API</option><option value=\"edge:public-image\">公開画像API</option><option value=\"edge:public-video\">公開動画API</option><option value=\"app_audit\">アプリの監査記録</option></select></label></div><div class=\"sec-table-wrap\"><table><thead><tr><th>記録時刻</th><th>種類</th><th>重要度</th><th>対象</th><th>結果</th><th>詳細</th></tr></thead><tbody id=\"sec-events\"></tbody></table></div><p id=\"sec-event-count\" class=\"sec-footnote\">—</p><button id=\"sec-more\" type=\"button\" hidden>さらに読み込む</button></section>\n <section class=\"sec-view sec-card\" data-sec-panel=\"incidents\" hidden><div class=\"sec-card-head\"><div><h2>インシデント</h2><p>同じ接続元で5分間に10件以上のシグナル、またはサーバーエラーをまとめます。</p></div></div><div id=\"sec-incidents\"></div></section>\n <section class=\"sec-view\" data-sec-panel=\"coverage\" hidden><div class=\"sec-card\"><h2>監視範囲と収集状態</h2><p>この画面に表示できる記録と、別途連携が必要な記録を区別しています。</p><div id=\"sec-coverage\"></div><div class=\"sec-coverage-static\"><article><h3>Vercel Firewall / DDoS対策</h3><span class=\"sec-badge neutral\">外部ログ未連携</span><p>Vercelがアプリ到達前に遮断した通信は、ここの件数に含まれません。</p><a href=\"https://vercel.com/toshiki-endos-projects/mefrion/firewall\" target=\"_blank\" rel=\"noopener noreferrer\">Vercelの公式画面で確認 ↗</a></article><article><h3>Supabase Auth / DB REST / Storageへの直接通信</h3><span class=\"sec-badge neutral\">拒否ログ未連携</span><p>Edge Functionを通らない直接アクセスの拒否は、この画面だけでは網羅できません。</p><a href=\"https://supabase.com/dashboard/project/pbnimpqrthvznbwewtcf/logs\" target=\"_blank\" rel=\"noopener noreferrer\">Supabaseの公式ログを開く ↗</a></article></div></div><div class=\"sec-card\"><h2>記録の取り扱い</h2><ul id=\"sec-limitations\"></ul><p>詳細ログは最大30日・10万件を目安に毎分整理し、時間別集計は最大90日、対応記録は最終更新から最大90日保存します。IPアドレス・メールアドレス・パスワード・認証コード・リクエスト本文は保存しません。ログの保存上限や送信エラーによる欠落がある場合は収集状態へ表示します。</p><p id=\"sec-retention\" class=\"sec-footnote\"></p></div></section>\n <footer class=\"sec-footer\">検知は調査の手がかりです。攻撃の確定や侵入成功を示すものではありません。<span id=\"sec-quality\"></span></footer>\n </div></div>\n <dialog id=\"sec-detail\" aria-labelledby=\"sec-detail-title\"><div class=\"sec-detail-head\"><h2 id=\"sec-detail-title\">記録の詳細</h2><button id=\"sec-detail-close\" type=\"button\" aria-label=\"詳細を閉じる\">×</button></div><dl id=\"sec-detail-body\"></dl><p>対象URLは個人情報を除去した形式です。元のIPアドレスや送信内容は記録していません。</p></dialog>\n</section>\n<!-- security-panel-end --><section id=\"confirmation\" hidden><h2>対応内容を確認</h2><p id=\"confirm-target\"></p><p id=\"confirm-reason\"></p><button id=\"confirm-review\">この対応を記録する</button><button id=\"cancel-review\">取り消す</button></section><section id=\"queue\"></section><section id=\"seed-section\" hidden><h1>運営Pet・承認・予約</h1><p>個別のPetログインは不要です。編集・承認・配信の権限をサーバーで確認します。運営が制作または管理する投稿が含まれる場合があることを、ヘルプと利用条件へ説明します。架空の反応・実体験は作成しません。</p><p id=\"seed-metrics\"></p><p id=\"seed-permissions\"></p><details id=\"seed-policy\"><summary>UGC優先比率・監査</summary><label>運営投稿の上限比率<input id=\"seed-ratio\" type=\"number\" min=\"0\" max=\"1\" step=\"0.05\" value=\"0.5\"></label><button id=\"seed-ratio-save\">上限比率を保存</button><button id=\"seed-audit-refresh\">操作監査を表示</button><div id=\"seed-audit\"></div></details><label>投稿主体<select id=\"seed-publisher\"></select></label><label>一括登録CSV<textarea id=\"seed-csv\" rows=\"6\" placeholder=\"key,name,species,breed,introduction,source\"></textarea></label><button id=\"seed-preview-button\">登録前プレビュー</button><div id=\"seed-preview\"></div><button id=\"seed-create\">プレビューしたPetを一括登録</button><label>運営Petを検索<input id=\"seed-search\" type=\"search\"></label><h2>投稿の一括下書き</h2><p>写真IDは素材の一覧で確認してください。複数枚は | で区切ります。入力予定日時は承認後に予約を確定します。</p><label>一括投稿CSV<textarea id=\"seed-post-csv\" rows=\"5\" placeholder=\"pet_id,photo_ids,body,planned_at\"></textarea></label><button id=\"seed-batch-preview\">一括投稿プレビュー</button><div id=\"seed-batch-list\"></div><button id=\"seed-batch-save\">確認した投稿を一括下書き保存</button><h2>投稿予定カレンダー</h2><div id=\"seed-calendar\"></div><div id=\"seed-list\"></div></section></main></body></html>\n"}};
const BASE="https://pbnimpqrthvznbwewtcf.supabase.co";
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const common={"Cache-Control":"no-store","X-Content-Type-Options":"nosniff","Referrer-Policy":"no-referrer","X-Frame-Options":"DENY"};
export default {async fetch(request,env={}){
 if(new URL(request.url).pathname.startsWith("/internal-backup/"))return backupHandler(request,env);
 const url=new URL(request.url);
 if(!["GET","HEAD"].includes(request.method))return new Response("Method not allowed",{status:405,headers:common});
 let pathname=url.pathname;
 if(pathname==="/")pathname="/index.html";
 if(pathname==="/console")pathname="/console/";
 if(pathname==="/privacy")pathname="/privacy.html";
 if(pathname==="/terms")pathname="/terms.html";
 if(PAGES[pathname])return new Response(request.method==="HEAD"?null:PAGES[pathname].body,{headers:{...common,"Content-Type":PAGES[pathname].type,...(pathname.startsWith("/console")?{"X-Robots-Tag":"noindex, nofollow","Content-Security-Policy":`default-src 'self'; connect-src 'self' ${BASE}; img-src 'self' blob: data:; style-src 'self' 'unsafe-inline'; script-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'none'`}:{})}});
 if(pathname==="/healthz")return new Response(JSON.stringify({ok:true,service:"MEFRION public pages"}),{headers:{...common,"Content-Type":"application/json"}});
 const match=pathname.match(/^\/(cloud-shared|cloud-development-shared)\/([0-9a-f-]+)$/i);
 if(match&&uuid.test(match[2])){
  const sharedBase=match[1]==="cloud-shared"?BASE:"https://pmrvzpuznwzuejbuhaqm.supabase.co";
  try{
   const upstream=await fetch(sharedBase+"/functions/v1/shared-page?post="+encodeURIComponent(match[2]),{headers:{"Cache-Control":"no-store"},signal:AbortSignal.timeout(15000)});
   if(![200,404,503].includes(upstream.status))return new Response("共有を読み込めません。もう一度お試しください。",{status:503,headers:common});
   const body=await upstream.text();
   if(body.length>500000)return new Response("共有を読み込めません。",{status:503,headers:common});
   return new Response(request.method==="HEAD"?null:body,{status:upstream.status,headers:{...common,"Content-Type":"text/html; charset=utf-8","Content-Security-Policy":`default-src 'none'; style-src 'unsafe-inline'; img-src ${sharedBase}; frame-ancestors 'none'; base-uri 'none'; form-action 'none'`}});
  }catch{return new Response("共有を読み込めません。もう一度お試しください。",{status:503,headers:common});}
 }
 return new Response("ページが見つかりません。",{status:404,headers:{...common,"Content-Type":"text/plain; charset=utf-8"}});
}};
